// --- Queue Implementation ---

// Time: O(1) amortized per operation
// Space: O(n)

#include <vector>
#include <stdexcept>

class Queue {
public:
    Queue(int capacity) : capacity(capacity), front(0), rear(-1), size(0), data(capacity) {}

    void enqueue(int value) {
        if (size == capacity) {
            throw std::overflow_error("Queue is full");
        }
        rear = (rear + 1) % capacity;
        data[rear] = value;
        size++;
    }

    int dequeue() {
        if (size == 0) {
            throw std::underflow_error("Queue is empty");
        }
        int value = data[front];
        front = (front + 1) % capacity;
        size--;
        return value;
    }

    int frontElement() const {
        if (size == 0) {
            throw std::underflow_error("Queue is empty");
        }
        return data[front];
    }

    bool isEmpty() const {
        return size == 0;
    }

private:
    int capacity;
    int front;
    int rear;
    int size;
    std::vector<int> data;
};

// --- Deque Implementation ---

// Time: O(1) amortized per operation
// Space: O(n)

#include <deque>

class Deque {
public:
    void push_back(int value) {
        dq.push_back(value);
    }

    void push_front(int value) {
        dq.push_front(value);
    }

    int pop_back() {
        if (dq.empty()) {
            throw std::underflow_error("Deque is empty");
        }
        int value = dq.back();
        dq.pop_back();
        return value;
    }

    int pop_front() {
        if (dq.empty()) {
            throw std::underflow_error("Deque is empty");
        }
        int value = dq.front();
        dq.pop_front();
        return value;
    }

    int backElement() const {
        if (dq.empty()) {
            throw std::underflow_error("Deque is empty");
        }
        return dq.back();
    }

    int frontElement() const {
        if (dq.empty()) {
            throw std::underflow_error("Deque is empty");
        }
        return dq.front();
    }

    bool isEmpty() const {
        return dq.empty();
    }

private:
    std::deque<int> dq;
};

