            if (disc[v] == -1) {
                parent[v] = u;
                children++;
                dfs(dfs, v);
                low[u] = std::min(low[u], low[v]);

                if (parent[u] == -1 && children > 1)
                    articulation[u] = true;
                if (parent[u] != -1 && low[v] >= disc[u])
                    articulation[u] = true;
            } else if (v != parent[u]) {
                low[u] = std::min(low[u], disc[v]);
            }
        }
    };

    for (int i = 0; i < n; ++i) {
        if (disc[i] == -1)
            dfs(dfs, i);
    }

    return articulation;
}

