// --- Space: O(V)

#include <vector>
#include <deque>
#include <limits>

using namespace std;
typedef long long ll;

class Graph {
public:
    int n; // Number of vertices
    vector<vector<pair<int, int>>> adj; // Adjacency list with weights

    Graph(int n) : n(n), adj(n) {}

    void addEdge(int u, int v, int w) {
        adj[u].emplace_back(v, w);
        adj[v].emplace_back(u, w); // For undirected graph
    }

    vector<ll> bfs01(int start) {
        vector<ll> dist(n, numeric_limits<ll>::max());
        deque<int> q;
        dist[start] = 0;
        q.push_front(start);

        while (!q.empty()) {
            int u = q.front();
            q.pop_front();

            for (auto [v, w] : adj[u]) {
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    if (w == 0) {
                        q.push_front(v);
                    } else {
                        q.push_back(v);
                    }
                }
            }
        }

        return dist;
    }
};

