// --- Gaussian Elimination ---

#include <vector>
#include <array>
#include <algorithm>
#include <cmath>

using namespace std;
typedef long long ll;

// Function to perform Gaussian Elimination on a matrix
bool gaussianElimination(vector<vector<ll>>& A, vector<ll>& b) {
    int n = A.size(), m = A[0].size() - 1;
    for (int i = 0; i < n; ++i) {
        // Find pivot row
        int max_row = i;
        for (int j = i + 1; j < n; ++j) {
            if (abs(A[j][i]) > abs(A[max_row][i])) {
                max_row = j;
            }
        }
        // Swap rows
        if (max_row != i) {
            swap(A[i], A[max_row]);
            swap(b[i], b[max_row]);
        }
        // Eliminate current variable
        for (int j = i + 1; j < n; ++j) {
            ll factor = A[j][i] / A[i][i];
            for (int k = i; k <= m; ++k) {
                A[j][k] -= factor * A[i][k];
            }
            b[j] -= factor * b[i];
        }
    }
    // Back-substitution
    for (int i = n - 1; i >= 0; --i) {
        b[i] /= A[i][i];
        for (int j = i - 1; j >= 0; --j) {
            b[j] -= A[j][i] * b[i];
        }
    }
    return true;
}

