// --- Ternary Search Implementation ---

// Function to perform ternary search on a unimodal array
int ternarySearch(const std::vector<int>& arr, int left, int right) {
    // Base case: if the subarray has only one element
    if (right >= left) {
        int mid1 = left + (right - left) / 3;
        int mid2 = right - (right - left) / 3;

        // If arr[mid1] is the maximum, return it
        if (arr[mid1] > arr[mid2])
            return ternarySearch(arr, left, mid1);

        // If arr[mid2] is the maximum, return it
        if (arr[mid2] > arr[mid1])
            return ternarySearch(arr, mid2, right);

        // If neither is the maximum, search in the middle third
        return ternarySearch(arr, mid1 + 1, mid2 - 1);
    }

    // If the subarray has no elements, return -1 (not found)
    return -1;
}

// --- Usage Example ---

