// --- build adjacency list ---
struct TrieNode {
    TrieNode* children[2] = {nullptr, nullptr}; // 0 and 1
};

TrieNode* buildTrie(const vector<int>& nums) {
    TrieNode* root = new TrieNode();
    for (int num : nums) {
        TrieNode* node = root;
        for (int i = 31; i >= 0; --i) { // Assuming 32-bit integers
            int bit = (num >> i) & 1;
            if (!node->children[bit]) {
                node->children[bit] = new TrieNode();
            }
            node = node->children[bit];
        }
    }
    return root;
}

// --- find maximum XOR ---
int maxXOR(TrieNode* root, int num) {
    int max_xor = 0;
    TrieNode* node = root;
    for (int i = 31; i >= 0; --i) {
        int bit = (num >> i) & 1;
        if (node->children[!bit]) { // Try the opposite bit first
            max_xor |= (1 << i);
            node = node->children[!bit];
        } else {
            node = node->children[bit];
        }
    }
    return max_xor;
}

