// --- Z-Function Implementation ---

#include <vector>
#include <string>
using namespace std;

// Function to compute the Z-Function for a given string
vector<int> z_function(const string& s) {
    int n = s.size();
    vector<int> z(n);
    int l = 0, r = 0; // Initialize the window [l, r]

    // --- Compute Z-Function ---
    for (int i = 1; i < n; ++i) {
        if (i <= r) {
            z[i] = min(r - i + 1, z[i - l]); // Use previously computed values
        }
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) {
            ++z[i]; // Extend the match
        }
        if (i + z[i] - 1 > r) {
            l = i; // Update the window
            r = i + z[i] - 1;
        }
    }
    return z;
}

