    int n, m;
    std::cin >> n >> m;
    build(0, 0, n - 1);
    for (int i = 0; i < m; ++i) {
        int u, v;
        std::cin >> u >> v;
        update(0, 0, n - 1, first[u]);
        update(0, 0, n - 1, first[v]);
        std::cout << query(0, 0, n - 1, first[u], last[u]) << std::endl;
    }
    return 0;
}

