// --- build adjacency list ---
std::vector<std::vector<int>> adj;

// --- binary lifting table ---
std::vector<std::vector<int>> lift;
int maxLevel;

// --- dfs to populate the binary lifting table ---
void dfs(int u, int p) {
    parent[u] = p;
    for (int v : adj[u]) {
        if (v != p) {
            depth[v] = depth[u] + 1;
            lift[v][0] = p;
            for (int k = 1; k <= maxLevel; ++k) {
                lift[v][k] = lift[lift[v][k-1]][k-1];
            }
            dfs(v, u);
        }
    }
}

// --- function to find LCA using binary lifting ---
int lca(int u, int v) {
    if (depth[u] > depth[v]) std::swap(u, v);
    for (int k = maxLevel; k >= 0; --k) {
        if ((depth[v] - depth[u]) & (1 << k)) {
            v = lift[v][k];
        }
    }
    if (u == v) return u;
    for (int k = maxLevel; k >= 0; --k) {
        if (lift[u][k] != lift[v][k]) {
            u = lift[u][k];
            v = lift[v][k];
        }
    }
    return parent[u];
}

// --- complexity comment block ---
// Time: O(n log n) for preprocessing, O(log n) per LCA query
// Space: O(n log n) for storing the binary lifting table

