// --- build adjacency list ---
struct Edge {
    int to, weight;
};

vector<vector<Edge>> adj;
vector<int> parent, depth, head, pos;
int timer = 0;

// --- HLD functions ---
void dfs(int u, int p) {
    parent[u] = p;
    depth[u] = depth[p] + 1;
    for (auto& [v, w] : adj[u]) {
        if (v != p) {
            dfs(v, u);
        }
    }
}

void decompose(int u, int h) {
    head[u] = h;
    pos[u] = timer++;
    for (auto& [v, w] : adj[u]) {
        if (depth[v] > depth[adj[u][0].to]) {
            adj[u][0].to = v; // heavy child
        }
    }
    for (auto& [v, w] : adj[u]) {
        if (v != parent[u] && v != adj[u][0].to) {
            decompose(v, v);
        }
    }
}

// --- Segment Tree functions ---
vector<long long> segtree;

void build(int node, int tl, int tr) {
    if (tl == tr) {
        segtree[node] = 0; // initial value
    } else {
        int tm = (tl + tr) / 2;
        build(node * 2, tl, tm);
        build(node * 2 + 1, tm + 1, tr);
        segtree[node] = segtree[node * 2] + segtree[node * 2 + 1];
    }
}

void update(int node, int tl, int tr, int pos, long long val) {
    if (tl == tr) {
        segtree[node] += val;
    } else {
        int tm = (tl + tr) / 2;
        if (pos <= tm) {
            update(node * 2, tl, tm, pos, val);
        } else {
            update(node * 2 + 1, tm + 1, tr, pos, val);
        }
        segtree[node] = segtree[node * 2] + segtree[node * 2 + 1];
    }
}

long long query(int node, int tl, int tr, int l, int r) {
    if (l > r) return 0;
    if (l == tl && r == tr) return segtree[node];
    int tm = (tl + tr) / 2;
    return query(node * 2, tl, tm, l, min(r, tm)) + query(node * 2 + 1, tm + 1, tr, max(l, tm + 1), r);
}

// --- LCA functions ---
vector<int> euler, level;
int hld_size;

void euler_tour(int u, int p) {
    euler.push_back(u);
    level.push_back(depth[u]);
    for (auto& [v, w] : adj[u]) {
        if (v != p) {
            euler_tour(v, u);
            euler.push_back(u);
        }
    }
}

int lca(int u, int v) {
    while (hld_size > level[u] - level[v]) {
        u = parent[head[u]];
    }
    while (hld_size > level[v] - level[u]) {
        v = parent[head[v]];
    }
    while (u != v) {
        u = parent[u];
        v = parent[v];
    }
    return u;
}

// --- Path Queries functions ---
void preprocess(int n) {
    adj.resize(n + 1);
    parent.resize(n + 1);
    depth.resize(n + 1);
    head.resize(n + 1);
    pos.resize(n + 1);
    segtree.resize(4 * n);

    dfs(1, -1);
    decompose(1, 1);
    euler_tour(1, -1);
    hld_size = euler.size();

    build(1, 0, hld_size - 1);
}

void update_path(int u, int v, long long val) {
    int lca_node = lca(u, v);
    if (pos[u] < pos[v]) {
        update(1, 0, hld_size - 1, pos[u], val);
        update(1, 0, hld_size - 1, pos[v], val);
        update(1, 0, hld_size - 1, pos[lca_node], -2 * val);
    } else {
        update(1, 0, hld_size - 1, pos[v], val);
        update(1, 0, hld_size - 1, pos[u], val);
        update(1, 0, hld_size - 1, pos[lca_node], -2 * val);
    }
}

long long query_path(int u, int v) {
    int lca_node = lca(u, v);
    return query(1, 0, hld_size - 1, pos[u], pos[v]) + query(1, 0, hld_size - 1, pos[lca_node], pos[lca_node]);
}

