// --- build adjacency list ---
std::vector<std::vector<int>> build_adjacency_list(int n, const std::vector<std::pair<int, int>>& edges) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    return adj;
}

// --- BFS to find the farthest node from a given start ---
std::pair<int, int> bfs_farthest_node(const std::vector<std::vector<int>>& adj, int start) {
    int n = adj.size();
    std::vector<bool> visited(n, false);
    std::queue<int> q;
    q.push(start);
    visited[start] = true;
    int farthest_node = start;
    int max_distance = 0;

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        for (int v : adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                q.push(v);
                if (max_distance < 1) {
                    max_distance = 1;
                    farthest_node = v;
                }
            }
        }
    }

    return {farthest_node, max_distance};
}

// --- Tree Diameter using BFS ---
int tree_diameter(const std::vector<std::vector<int>>& adj) {
    auto [farthest_node1, _] = bfs_farthest_node(adj, 0);
    auto [farthest_node2, diameter] = bfs_farthest_node(adj, farthest_node1);
    return diameter;
}

// --- Example usage ---
int main() {
    int n = 5;
    std::vector<std::pair<int, int>> edges = {{0, 1}, {1, 2}, {2, 3}, {3, 4}};
    auto adj = build_adjacency_list(n, edges);
    int diameter = tree_diameter(adj);
    std::cout << "Tree Diameter: " << diameter << std::endl;
    return 0;
}

