// --- build adjacency list ---
struct Fenwick2D {
    int n, m;
    vector<vector<long long>> tree;

    Fenwick2D(int n, int m) : n(n), m(m), tree(n + 1, vector<long long>(m + 1)) {}

    // --- update ---
    void update(int x, int y, long long val) {
        for (int i = x; i <= n; i += i & -i) {
            for (int j = y; j <= m; j += j & -j) {
                tree[i][j] += val;
            }
        }
    }

    // --- prefix sum query ---
    long long query(int x, int y) {
        long long sum = 0;
        for (int i = x; i > 0; i -= i & -i) {
            for (int j = y; j > 0; j -= j & -j) {
                sum += tree[i][j];
            }
        }
        return sum;
    }

    // --- range query ---
    long long query(int x1, int y1, int x2, int y2) {
        return query(x2, y2) - query(x1 - 1, y2) - query(x2, y1 - 1) + query(x1 - 1, y1 - 1);
    }
};

// --- usage example ---
int main() {
    Fenwick2D ft(3, 3);
    ft.update(1, 1, 1);
    ft.update(1, 2, 2);
    ft.update(2, 1, 4);
    ft.update(2, 2, 5);

    cout << ft.query(1, 1, 2, 2) << endl; // Output: 12
    return 0;
}

