// --- Chtholly Tree (ODT) Implementation ---

// Time: O(n log n) — Space: O(n)

#include <vector>
#include <set>
#include <algorithm>

using namespace std;

struct Node {
    int val; // Value of the node
    bool lazy; // Lazy propagation flag
    Node(int v = 0, bool l = false) : val(v), lazy(l) {}
};

class ChthollyTree {
private:
    vector<Node> tree;
    set<int> boundaries; // Boundaries of intervals

public:
    ChthollyTree(int n) : tree(n * 4), boundaries({0, n}) {}

    // --- Build the tree ---
    void build(int node, int start, int end) {
        if (start == end) {
            tree[node] = Node(0, false);
            return;
        }
        int mid = (start + end) / 2;
        build(node * 2, start, mid);
        build(node * 2 + 1, mid + 1, end);
        tree[node] = Node(0, false);
    }

    // --- Propagate lazy updates ---
    void propagate(int node, int start, int end) {
        if (!tree[node].lazy) return;
        int mid = (start + end) / 2;
        tree[node * 2] = Node(tree[node].val, true);
        tree[node * 2 + 1] = Node(tree[node].val, true);
        tree[node].lazy = false;
    }

    // --- Update interval ---
    void update(int node, int start, int end, int l, int r, int val) {
        if (l > end || r < start) return; // Out of bounds
        if (l <= start && end <= r) {
            tree[node] = Node(val, true);
            return;
        }
        propagate(node, start, end);
        int mid = (start + end) / 2;
        update(node * 2, start, mid, l, r, val);
        update(node * 2 + 1, mid + 1, end, l, r, val);
    }

    // --- Query point ---
    int query(int node, int start, int end, int idx) {
        if (start == end) return tree[node].val;
        propagate(node, start, end);
        int mid = (start + end) / 2;
        if (idx <= mid) return query(node * 2, start, mid, idx);
        else return query(node * 2 + 1, mid + 1, end, idx);
    }
};

