// --- DSU with Rollback Implementation ---

// Time: O(n log n) for union and find operations
// Space: O(n) for parent and rank arrays

#include <vector>
#include <stack>
#include <algorithm>

using namespace std;

struct DSUWithRollback {
    vector<int> parent, rank, history;
    stack<int> historyStack;

    DSUWithRollback(int n) : parent(n), rank(n, 1) {
        for (int i = 0; i < n; ++i) parent[i] = i;
    }

    int find(int u) {
        if (parent[u] != u) {
            historyStack.push(u);
            parent[u] = find(parent[u]);
        }
        return parent[u];
    }

    void unionSets(int u, int v) {
        int pu = find(u), pv = find(v);
        if (pu != pv) {
            historyStack.push(pu);
            historyStack.push(pv);
            if (rank[pu] > rank[pv]) {
                parent[pv] = pu;
            } else if (rank[pu] < rank[pv]) {
                parent[pu] = pv;
            } else {
                parent[pu] = pv;
                rank[pv]++;
            }
        }
    }

    void rollback() {
        while (!historyStack.empty()) {
            int u = historyStack.top();
            historyStack.pop();
            parent[u] = u;
        }
    }
};

