// --- Implicit Treap Implementation ---

#include <vector>
#include <random>
#include <functional>

// --- Node Structure ---
struct Node {
    int key; // Key of the node
    int priority; // Priority of the node
    Node* left; // Left child
    Node* right; // Right child

    Node(int k, int p) : key(k), priority(p), left(nullptr), right(nullptr) {}
};

// --- Implicit Treap Class ---
class ImplicitTreap {
private:
    Node* root;
    std::mt19937 rng; // Random number generator for priorities

public:
    ImplicitTreap() : root(nullptr), rng(std::random_device{}()) {}

    // --- Insert a key with a random priority ---
    void insert(int key) {
        int priority = rng();
        root = insert(root, key, priority);
    }

    // --- Insert helper function ---
    Node* insert(Node* node, int key, int priority) {
        if (!node) return new Node(key, priority);
        if (priority > node->priority) { // Higher priority means it should be the root of the subtree
            Node* newRoot = new Node(key, priority);
            split(node, key, newRoot->left, newRoot->right);
            return newRoot;
        } else {
            if (key < node->key) {
                node->left = insert(node->left, key, priority);
            } else {
                node->right = insert(node->right, key, priority);
            }
        }
        return node;
    }

    // --- Split the tree into two based on a key ---
    void split(Node* node, int key, Node*& left, Node*& right) {
        if (!node) {
            left = right = nullptr;
            return;
        }
        if (key < node->key) {
            split(node->left, key, left, node->left);
            right = node;
        } else {
            split(node->right, key, node->right, right);
            left = node;
        }
    }

    // --- Merge two trees into one ---
    Node* merge(Node* left, Node* right) {
        if (!left || !right) return left ? left : right;
        if (left->priority > right->priority) {
            left->right = merge(left->right, right);
            return left;
        } else {
            right->left = merge(left, right->left);
            return right;
        }
    }

    // --- Destructor to clean up the tree ---
    ~ImplicitTreap() {
        destroy(root);
    }

    // --- Helper function to destroy the tree ---
    void destroy(Node* node) {
        if (node) {
            destroy(node->left);
            destroy(node->right);
            delete node;
        }
    }
};

// --- Complexity Note ---
// Time: O(log n) for insert, split, and merge operations
// Space: O(n) for storing the tree

