// --- Merge Sort Tree Implementation ---

#include <vector>
#include <algorithm>

using namespace std;

// --- Segment Tree Node ---
struct Node {
    int value; // Value of the node
    Node(int v) : value(v) {}
};

// --- Merge Sort Tree ---
class MergeSortTree {
private:
    vector<vector<Node>> tree; // Segment tree
    vector<int> arr; // Original array

    // Helper function to build the segment tree
    void build(int node, int start, int end) {
        if (start == end) {
            tree[node].push_back(Node(arr[start]));
        } else {
            int mid = (start + end) / 2;
            build(2 * node, start, mid);
            build(2 * node + 1, mid + 1, end);
            merge(tree[2 * node].begin(), tree[2 * node].end(),
                  tree[2 * node + 1].begin(), tree[2 * node + 1].end(),
                  back_inserter(tree[node]));
        }
    }

    // Helper function to query the segment tree
    int query(int node, int start, int end, int l, int r) {
        if (r < start || end < l) return 0; // Out of range
        if (l <= start && end <= r) return tree[node].back().value; // Inside range
        int mid = (start + end) / 2;
        return query(2 * node, start, mid, l, r) + query(2 * node + 1, mid + 1, end, l, r);
    }

public:
    // Constructor to initialize the Merge Sort Tree
    MergeSortTree(const vector<int>& arr) : arr(arr) {
        int n = arr.size();
        tree.resize(4 * n); // Allocate enough space for the segment tree
        build(1, 0, n - 1);
    }

    // Function to query the sum of elements in range [l, r]
    int rangeQuery(int l, int r) {
        return query(1, 0, arr.size() - 1, l, r);
    }
};

