// --- Mo's Algorithm Implementation ---

#include <vector>
#include <algorithm>
#include <cmath>

// Time: O((N + Q) * sqrt(N)) — Space: O(N)

struct Query {
    int l, r, idx;
};

std::vector<int> moAlgorithm(const std::vector<int>& arr, const std::vector<Query>& queries) {
    int n = arr.size(), q = queries.size();
    int block_size = std::sqrt(n);
    std::vector<int> result(q);
    std::vector<int> freq(n + 1, 0);
    int current_l = 0, current_r = -1;

    // --- Sort queries by block and within blocks ---
    std::vector<Query> sorted_queries(queries);
    for (int i = 0; i < q; ++i) {
        sorted_queries[i].idx = i;
    }
    std::sort(sorted_queries.begin(), sorted_queries.end(), [&](const Query& a, const Query& b) {
        int block_a = a.l / block_size, block_b = b.l / block_size;
        if (block_a == block_b) return a.r < b.r;
        return block_a < block_b;
    });

    // --- Process queries ---
    for (const Query& query : sorted_queries) {
        int l = query.l, r = query.r;

        // --- Add elements to the current segment ---
        while (current_r < r) {
            ++freq[arr[++current_r]];
        }

        // --- Remove elements from the current segment ---
        while (current_l > l) {
            ++freq[arr[--current_l]];
        }

        // --- Remove elements outside the current segment ---
        while (current_r > r) {
            --freq[arr[current_r--]];
        }

        // --- Remove elements before the current segment ---
        while (current_l < l) {
            --freq[arr[current_l++]];
        }

        // --- Store the result for the current query ---
        result[query.idx] = std::accumulate(freq.begin(), freq.end(), 0);
    }

    return result;
}

