// --- Time Complexity: O(n + q * sqrt(n))
// --- Space Complexity: O(n)

#include <vector>
#include <cmath>

struct SquareRootDecomposition {
    std::vector<int> block_sums;
    std::vector<int> original_values;
    int block_size;

    // --- Constructor ---
    SquareRootDecomposition(const std::vector<int>& values) : original_values(values) {
        int n = values.size();
        block_size = static_cast<int>(std::sqrt(n));
        block_sums.resize(block_size + 1, 0);

        // --- Build block sums ---
        for (int i = 0; i < n; ++i) {
            block_sums[i / block_size] += values[i];
        }
    }

    // --- Update value at index i to new_value ---
    void update(int i, int new_value) {
        block_sums[i / block_size] -= original_values[i];
        block_sums[i / block_size] += new_value;
        original_values[i] = new_value;
    }

    // --- Query sum of values in range [left, right] ---
    int query(int left, int right) {
        int result = 0;
        for (int i = left; i <= right; ++i) {
            result += original_values[i];
        }
        return result;
    }
};

