// Time: O(log n) for most operations - Space: O(n)

#include <iostream>
#include <vector>
#include <queue>
#include <random>

using namespace std;

struct Node {
    int key, priority;
    Node* left, * right;
    Node(int k, int p) : key(k), priority(p), left(nullptr), right(nullptr) {}
};

class Treap {
private:
    Node* root;
    mt19937 rng;

    // --- Helper Functions ---

    Node* merge(Node* l, Node* r) {
        if (!l || !r) return l ? l : r;
        if (l->priority > r->priority) {
            l->right = merge(l->right, r);
            return l;
        } else {
            r->left = merge(l, r->left);
            return r;
        }
    }

    pair<Node*, Node*> split(Node* node, int key) {
        if (!node) return {nullptr, nullptr};
        if (node->key < key) {
            auto [l, r] = split(node->right, key);
            node->right = l;
            return {node, r};
        } else {
            auto [l, r] = split(node->left, key);
            node->left = r;
            return {l, node};
        }
    }

public:
    Treap() : root(nullptr), rng(random_device{}()) {}

    // --- Insertion ---

    void insert(int key) {
        int priority = rng();
        auto [l, r] = split(root, key);
        root = merge(merge(l, new Node(key, priority)), r);
    }

    // --- Deletion ---

    void erase(int key) {
        auto [l, r] = split(root, key);
        auto [ll, lr] = split(l, key - 1);
        root = merge(merge(ll, lr->right), r);
        delete lr;
    }

