// --- build adjacency list ---
std::vector<std::pair<int, int>> buildCartesianTree(const std::vector<int>& arr) {
    std::stack<int> s;
    std::vector<std::pair<int, int>> tree(arr.size());

    for (int i = 0; i < arr.size(); ++i) {
        // --- find next greater element ---
        while (!s.empty() && arr[s.top()] < arr[i]) {
            s.pop();
        }

        if (!s.empty()) {
            tree[s.top()].second = i;
        }

        s.push(i);
    }

    // --- set left child ---
    while (s.size() > 1) {
        int top = s.top(); s.pop();
        tree[top].first = s.top();
    }

    return tree;
}

