std::vector<std::vector<int>> build_adjacency_list(const std::vector<int>& tiles) {
    int n = tiles.size();
    std::vector<std::vector<int>> adj(n);
    for (int i = 0; i < n - 1; ++i) {
        if (tiles[i] == 3 || tiles[i + 1] == 3) {
            adj[i].push_back(i + 1);
            adj[i + 1].push_back(i);
        }
        if (tiles[i] == 1 || tiles[i + 1] == 1) {
            adj[i].push_back(i + 1);
            adj[i + 1].push_back(i);
        }
        if (tiles[i] == 1 || tiles[i + 1] == 4) {
            adj[i].push_back(i + 1);
            adj[i + 1].push_back(i);
        }
    }
    return adj;
}

// --- dp function ---
long long broken_profile_dp(const std::vector<int>& tiles, const std::vector<std::vector<int>>& adj) {
    int n = tiles.size();
    std::vector<long long> dp(1 << n, 0);
    dp[0] = 1;

    for (int i = 0; i < n; ++i) {
        std::vector<long long> new_dp(dp);
        for (int mask = 0; mask < (1 << n); ++mask) {
            if ((mask & (1 << i)) == 0) continue;
            bool valid = true;
            for (int j : adj[i]) {
                if ((mask & (1 << j)) != 0 && tiles[j] == tiles[i]) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                new_dp[mask] += dp[mask ^ (1 << i)];
            }
        }
        dp = new_dp;
    }

    return dp[(1 << n) - 1];
}

// --- usage example ---
int main() {
    std::vector<int> tiles = {3, 1, 4, 1, 5};
    auto adj = build_adjacency_list(tiles);
    long long result = broken_profile_dp(tiles, adj);
    std::cout << result << std::endl;
    return 0;
}

