// --- Convex Hull Trick Implementation ---

// Time: O(n log n) — Space: O(n)

#include <vector>
#include <algorithm>

struct Line {
    long long m, c; // slope and y-intercept
    Line(long long m = 0, long long c = 0) : m(m), c(c) {}
};

struct CHT {
    std::vector<Line> hull;

    // Add a new line to the convex hull
    void add(long long m, long long c) {
        Line l(m, c);
        while (hull.size() >= 2 && hull[hull.size() - 2].m * l.c + hull[hull.size() - 2].c <=
               hull.back().m * l.c + hull.back().c)
            hull.pop_back();
        hull.push_back(l);
    }

    // Query the minimum value of the convex hull at x
    long long query(long long x) {
        int l = 0, r = hull.size() - 1;
        while (l < r) {
            int m = (l + r) / 2;
            if (hull[m].m * x + hull[m].c <= hull[m + 1].m * x + hull[m + 1].c)
                r = m;
            else
                l = m + 1;
        }
        return hull[l].m * x + hull[l].c;
    }
};

