// --- build adjacency list ---
std::vector<std::vector<int>> build_adjacency_list(const std::vector<std::vector<int>>& distances) {
    int n = distances.size();
    std::vector<std::vector<int>> adj(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (distances[i][j] != -1) {
                adj[i].push_back(j);
            }
        }
    }
    return adj;
}

// --- dp on profiles ---
std::vector<std::vector<long long>> dp_on_profiles(const std::vector<std::vector<int>>& distances, int start) {
    int n = distances.size();
    std::vector<std::vector<long long>> dp(1 << n, std::vector<long long>(n, LLONG_MAX));
    dp[1 << start][start] = 0;

    for (int mask = 1; mask < (1 << n); ++mask) {
        for (int u = 0; u < n; ++u) {
            if (mask & (1 << u)) {
                for (int v : adj[u]) {
                    if (!(mask & (1 << v))) {
                        dp[mask | (1 << v)][v] = std::min(dp[mask | (1 << v)][v], dp[mask][u] + distances[u][v]);
                    }
                }
            }
        }
    }

    return dp;
}

// --- main function ---
int main() {
    int n, start;
    std::cin >> n >> start;
    std::vector<std::vector<int>> distances(n, std::vector<int>(n, -1));

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            std::cin >> distances[i][j];
        }
    }

    auto adj = build_adjacency_list(distances);
    auto dp = dp_on_profiles(distances, start);

    long long min_cost = LLONG_MAX;
    for (int i = 0; i < n; ++i) {
        min_cost = std::min(min_cost, dp[(1 << n) - 1][i] + distances[i][start]);
    }

    std::cout << min_cost << std::endl;
    return 0;
}

