struct Edge {
    int to, capacity;
};

using Graph = vector<vector<Edge>>;
using Flow = vector<long long>;
using Cost = vector<long long>;

// --- dp on subsets ---
Flow dp(int n, const Graph& g, const Flow& supply, const Flow& demand) {
    Flow f(1 << n, 0);
    for (int s = 0; s < (1 << n); ++s) {
        for (int i = 0; i < n; ++i) {
            if (s & (1 << i)) {
                int prev_s = s ^ (1 << i);
                for (const auto& e : g[i]) {
                    int j = e.to;
                    if ((s & (1 << j)) == 0) {
                        f[s] = max(f[s], f[prev_s] + min(e.capacity, supply[i] - demand[j]));
                    }
                }
            }
        }
    }
    return f;
}

// --- usage example ---
int main() {
    int n = 4; // number of vertices
    Graph g(n);
    g[0].push_back({1, 3});
    g[0].push_back({2, 4});
    g[1].push_back({3, 2});
    g[2].push_back({3, 5});
    g[1].push_back({2, 1});

    Flow supply = {7, 0, 0, 0};
    Flow demand = {0, 0, 0, 7};

    Flow f = dp(n, g, supply, demand);

    cout << "Maximum flow: " << f[(1 << n) - 1] << endl;
    return 0;
}

