// --- Patience Sorting Implementation ---

#include <vector>
#include <algorithm>

// Function to find the length of the longest increasing subsequence (LIS)
int patienceSorting(const std::vector<int>& nums) {
    if (nums.empty()) return 0;

    // Piles to represent chains
    std::vector<int> piles;

    for (int num : nums) {
        // Find the leftmost pile where the top element is >= num
        auto it = std::lower_bound(piles.begin(), piles.end(), num);

        if (it == piles.end()) {
            // If no such pile exists, create a new one
            piles.push_back(num);
        } else {
            // Otherwise, replace the top element of the found pile
            *it = num;
        }
    }

    // The number of piles is the length of the longest increasing subsequence
    return piles.size();
}

