// --- Longest Increasing Subsequence (LIS) using Divide & Conquer DP ---

#include <vector>
#include <algorithm>

// Function to find the length of the longest increasing subsequence
int lis(const std::vector<int>& nums) {
    if (nums.empty()) return 0;

    // tails[i] will be the smallest tail value for all increasing subsequences of length i+1
    std::vector<int> tails;

    for (int num : nums) {
        // Find the position to replace or extend the tails array
        auto it = std::lower_bound(tails.begin(), tails.end(), num);
        if (it == tails.end()) {
            // If num is larger than all tails, extend the tails array
            tails.push_back(num);
        } else {
            // Replace the first element that is not smaller than num
            *it = num;
        }
    }

    // The length of tails array is the length of the longest increasing subsequence
    return tails.size();
}

