// --- Knuth's Optimization for Interval DP ---

// Time: O(n^2) — Space: O(n^2)

#include <vector>
#include <algorithm>

using namespace std;
typedef long long ll;

// Function to apply Knuth's Optimization on a given DP problem
vector<vector<ll>> knuth_optimization(const vector<vector<ll>>& w) {
    int n = w.size();
    vector<vector<ll>> dp(n, vector<ll>(n, 0));

    // --- Precompute prefix sums for quick range sum queries ---
    vector<vector<ll>> prefix_sum(n, vector<ll>(n, 0));
    for (int i = 0; i < n; ++i) {
        for (int j = i; j < n; ++j) {
            prefix_sum[i][j] = (i > 0 ? prefix_sum[i-1][j] : 0) + w[i][j];
        }
    }

    // --- Fill the DP table using Knuth's Optimization ---
    for (int l = 2; l <= n; ++l) { // Length of interval
        for (int i = 0; i <= n - l; ++i) {
            int j = i + l - 1;
            dp[i][j] = prefix_sum[i][j]; // Base case for length 1
            for (int k = i; k < j; ++k) {
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k+1][j]);
            }
        }
    }

    return dp;
}

