// --- Li Chao Tree ---

// Time: O(log n) per query/update — Space: O(n)

#include <vector>
#include <algorithm>

struct Line {
    long long a, b;
    Line(long long a = 0, long long b = 0) : a(a), b(b) {}
    long long operator()(long long x) const { return a * x + b; }
};

struct LiChaoTree {
    std::vector<Line> tree;
    int n;

    LiChaoTree(int n) : n(n), tree(2 * n) {}

    // --- update ---
    void update(int pos, Line line) {
        pos += n;
        for (; pos > 1; pos >>= 1) {
            if (line(pos / 2) < tree[pos / 2](pos / 2)) {
                std::swap(line, tree[pos / 2]);
            }
        }
        tree[1] = line;
    }

    // --- query ---
    long long query(int l, int r, int pos = 1, int tl = 0, int tr = -1) {
        if (tr == -1) tr = n - 1;
        if (l > r) return std::numeric_limits<long long>::max();
        if (l == tl && r == tr) return tree[pos](l);
        int tm = (tl + tr) / 2;
        return std::min(query(l, std::min(r, tm), pos * 2, tl, tm), query(std::max(l, tm + 1), r, pos * 2 + 1, tm + 1, tr));
    }
};

