// --- zeta transform ---
std::vector<long long> zeta_transform(const std::vector<long long>& f) {
    int n = f.size();
    for (int s = 1; s < n; s <<= 1) {
        for (int i = 0; i < n; i += s + s) {
            for (int j = 0; j < s; ++j) {
                f[i + j + s] += f[i + j];
            }
        }
    }
    return f;
}

// --- inverse zeta transform ---
std::vector<long long> inverse_zeta_transform(const std::vector<long long>& f) {
    int n = f.size();
    for (int s = 1; s < n; s <<= 1) {
        for (int i = 0; i < n; i += s + s) {
            for (int j = 0; j < s; ++j) {
                f[i + j] -= f[i + j + s];
            }
        }
    }
    return f;
}

// --- sum over subsets dp ---
std::vector<long long> sum_over_subsets_dp(const std::vector<std::vector<int>>& adj, int root) {
    int n = adj.size();
    std::vector<long long> dp(1 << n, 0);
    dp[0] = 1;

    for (int s = 0; s < (1 << n); ++s) {
        int u = __builtin_ctz(s); // find the first set bit
        for (int v : adj[u]) {
            if (!(s & (1 << v))) {
                dp[s | (1 << v)] += dp[s];
            }
        }
    }

    return dp;
}

// --- main function for usage example ---
void solve() {
    int n, m;
    std::cin >> n >> m;
    std::vector<std::pair<int, int>> edges(m);
    for (int i = 0; i < m; ++i) {
        std::cin >> edges[i].first >> edges[i].second;
    }

    auto adj = build_adjacency_list(edges, n);
    auto dp = sum_over_subsets_dp(adj, 0);

    std::cout << dp[(1 << n) - 1] << std::endl;
}

