// --- build adjacency list ---
std::vector<std::vector<int>> build_adjacency_list(const std::vector<std::pair<int, int>>& edges, int n) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    return adj;
}

// --- hopcroft-karp algorithm ---
int hopcroft_karp(const std::vector<std::vector<int>>& adj, int n, int m) {
    std::vector<int> dist(n + m, -1);
    std::vector<int> match(n + m, -1);

    auto bfs = [&]() -> bool {
        std::queue<int> q;
        for (int u = 0; u < n; ++u) {
            if (match[u] == -1) {
                dist[u] = 0;
                q.push(u);
            } else {
                dist[u] = INT_MAX;
            }
        }
        dist[n + m] = INT_MAX;

        while (!q.empty()) {
            int u = q.front();
            q.pop();

            if (dist[u] < dist[n + m]) {
                for (int v : adj[u]) {
                    if (dist[match[v]] == -1) {
                        dist[match[v]] = dist[u] + 1;
                        q.push(match[v]);
                    }
                }
            }
        }

        return dist[n + m] != INT_MAX;
    };

    auto dfs = [&](int u) -> bool {
        if (u == n + m) {
            return true;
        }

        for (int v : adj[u]) {
            if (dist[match[v]] == dist[u] + 1) {
                dist[match[v]] = -1;
                if (dfs(match[v])) {
                    match[u] = v;
                    match[v] = u;
                    return true;
                }
            }
        }

        dist[u] = INT_MAX;
        return false;
    };

    int result = 0;
    while (bfs()) {
        for (int u = 0; u < n; ++u) {
            if (match[u] == -1 && dfs(u)) {
                ++result;
            }
        }
    }

    return result;
}

