// --- build adjacency list ---
struct Edge {
    int to, cap, rev;
};

vector<vector<Edge>> adj;

// --- add edge ---
void addEdge(int from, int to, int cap) {
    adj[from].push_back({to, cap, (int)adj[to].size()});
    adj[to].push_back({from, 0, (int)adj[from].size() - 1});
}

// --- bfs to find blocking flow ---
bool bfs(int s, int t, vector<int>& level) {
    fill(level.begin(), level.end(), -1);
    queue<int> q;
    q.push(s);
    level[s] = 0;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (const auto& e : adj[u]) {
            if (e.cap > 0 && level[e.to] == -1) {
                level[e.to] = level[u] + 1;
                q.push(e.to);
            }
        }
    }
    return level[t] != -1;
}

// --- dfs to find augmenting path ---
int dfs(int u, int t, int f, vector<int>& level) {
    if (u == t) return f;
    for (auto& e : adj[u]) {
        if (e.cap > 0 && level[e.to] == level[u] + 1) {
            int d = dfs(e.to, t, min(f, e.cap), level);
            if (d > 0) {
                e.cap -= d;
                adj[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

// --- dinic's algorithm ---
long long dinic(int s, int t) {
    long long flow = 0;
    vector<int> level;
    while (bfs(s, t, level)) {
        flow += dfs(s, t, INT_MAX, level);
    }
    return flow;
}

