// --- build adjacency list ---
std::vector<std::vector<int>> build_adjacency_list(const std::vector<std::pair<int, int>>& edges, int n) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    return adj;
}

// --- bfs to find augmenting path ---
bool bfs(const std::vector<std::vector<int>>& adj, const std::vector<int>& match, std::vector<int>& parent) {
    int n = adj.size();
    std::vector<bool> visited(n, false);
    std::queue<int> q;

    for (int u = 0; u < n; ++u) {
        if (match[u] == -1) {
            q.push(u);
            visited[u] = true;
            parent[u] = -1;
        }
    }

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        for (int v : adj[u]) {
            if (!visited[v] && match[v] != u) {
                visited[v] = true;
                parent[v] = u;
                if (match[v] == -1 || bfs(adj, match, parent))) {
                    match[v] = u;
                    match[u] = v;
                    return true;
                }
            }
        }
    }

    return false;
}

// --- hopcroft-karp algorithm for maximum matching ---
int hopcroft_karp(const std::vector<std::vector<int>>& adj, int n) {
    std::vector<int> match(n, -1);
    int result = 0;

    while (bfs(adj, match, std::vector<int>(n))) {
        ++result;
    }

    return result;
}

// --- find minimum vertex cover using maximum matching ---
std::vector<int> find_min_vertex_cover(const std::vector<std::vector<int>>& adj, int n) {
    std::vector<int> match(n, -1);
    std::vector<bool> visited(n, false);
    std::vector<int> cover;

    hopcroft_karp(adj, n);

    for (int u = 0; u < n; ++u) {
        if (match[u] == -1 && !visited[u]) {
            cover.push_back(u);
            visited[u] = true;
            for (int v : adj[u]) {
                if (match[v] != -1 && !visited[match[v]]) {
                    visited[match[v]] = true;
                }
            }
        }
    }

    return cover;
}

