// --- build adjacency list ---
struct Edge {
    int to, capacity, flow;
};

using Graph = vector<vector<Edge>>;

// --- bfs to find augmenting path ---
bool bfs(const Graph& graph, int s, int t, vector<int>& parent) {
    vector<bool> visited(graph.size(), false);
    queue<int> q;
    q.push(s);
    visited[s] = true;
    parent[s] = -1;

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        for (const auto& edge : graph[u]) {
            int v = edge.to;
            long long residual = edge.capacity - edge.flow;

            if (!visited[v] && residual > 0) {
                q.push(v);
                visited[v] = true;
                parent[v] = u;
                if (v == t) return true;
            }
        }
    }
    return false;
}

// --- edmonds-karp algorithm ---
long long edmondsKarp(Graph& graph, int s, int t) {
    vector<int> parent(graph.size());
    long long maxFlow = 0;

    while (bfs(graph, s, t, parent)) {
        long long pathFlow = LLONG_MAX;

        // --- find the maximum flow in the path ---
        for (int v = t; v != s; v = parent[v]) {
            int u = parent[v];
            for (auto& edge : graph[u]) {
                if (edge.to == v) {
                    pathFlow = min(pathFlow, edge.capacity - edge.flow);
                    break;
                }
            }
        }

        // --- update residual capacities of the edges and reverse edges along the path ---
        for (int v = t; v != s; v = parent[v]) {
            int u = parent[v];
            for (auto& edge : graph[u]) {
                if (edge.to == v) {
                    edge.flow += pathFlow;
                    break;
                }
            }
            for (auto& edge : graph[v]) {
                if (edge.to == u) {
                    edge.flow -= pathFlow;
                    break;
                }
            }
        }

        maxFlow += pathFlow;
    }
    return maxFlow;
}

