    vector<bool> visited(adj.size(), false);
    queue<int> q;
    q.push(s);
    visited[s] = true;

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        for (const auto& edge : adj[u]) {
            int v = edge.to;
            long long residual = edge.capacity - edge.flow;

            if (!visited[v] && residual > 0) {
                parent[v] = u;
                visited[v] = true;
                q.push(v);
            }
        }
    }

    return visited[t];
}

// --- edmonds-karp algorithm for max-flow ---
long long edmondsKarp(int s, int t) {
    long long maxFlow = 0;

    while (bfs(s, t)) {
        long long pathFlow = LLONG_MAX;

        // --- find the maximum flow in the path ---
        for (int v = t; v != s; v = parent[v]) {
            int u = parent[v];
            pathFlow = min(pathFlow, adj[u][findEdge(u, v)].capacity - adj[u][findEdge(u, v)].flow);
        }

        // --- update residual capacities of the edges and reverse edges along the path ---
        for (int v = t; v != s; v = parent[v]) {
            int u = parent[v];
            adj[u][findEdge(u, v)].flow += pathFlow;
            adj[v][findEdge(v, u)].flow -= pathFlow;
        }

        maxFlow += pathFlow;
    }

    return maxFlow;
}

// --- find the index of the edge from u to v ---
int findEdge(int u, int v) {
    for (int i = 0; i < adj[u].size(); ++i) {
        if (adj[u][i].to == v) {
            return i;
        }
