// --- Branch and Bound for Knapsack Problem ---

#include <vector>
#include <algorithm>

struct Item {
    int value;
    int weight;
};

// --- Function to compare items based on value-to-weight ratio ---
bool cmp(Item a, Item b) {
    return (double)a.value / a.weight > (double)b.value / b.weight;
}

// --- Branch and Bound function ---
int branchAndBound(std::vector<Item>& items, int capacity) {
    // Sort items by value-to-weight ratio in descending order
    std::sort(items.begin(), items.end(), cmp);

    int n = items.size();
    int bestValue = 0;
    std::vector<bool> taken(n, false);

    // --- Recursive function to explore the search tree ---
    auto explore = [&](int i, int currentWeight, int currentValue) {
        if (i == n) {
            bestValue = std::max(bestValue, currentValue);
            return;
        }

        // --- Branch 1: Include the current item ---
        if (currentWeight + items[i].weight <= capacity) {
            taken[i] = true;
            explore(i + 1, currentWeight + items[i].weight, currentValue + items[i].value);
            taken[i] = false;
        }

        // --- Branch 2: Exclude the current item ---
        explore(i + 1, currentWeight, currentValue);
    };

    explore(0, 0, 0);
    return bestValue;
}

