// --- Sprague-Grundy Theorem & Nim Implementation ---

// Function to calculate the Grundy number for a Nim game with given pile sizes
long long grundyNim(const std::vector<int>& piles) {
    // --- compute XOR of all pile sizes ---
    long long xorSum = 0;
    for (int pile : piles) {
        xorSum ^= pile; // XOR each pile size to get the overall Grundy number
    }
    return xorSum;
}

