// Function to calculate the Euclidean distance between two points
long long dist(const Point& p1, const Point& p2) {
    return (p1.x - p2.x) * (p1.x - p2.x) + (p1.y - p2.y) * (p1.y - p2.y);
}

// Function to find the closest pair in a strip of width delta around the line x = mid
long long stripClosest(const vector<Point>& strip, long long delta) {
    long long min_dist = numeric_limits<long long>::max();
    sort(strip.begin(), strip.end(), [](const Point& p1, const Point& p2) { return p1.y < p2.y; });

    for (size_t i = 0; i < strip.size(); ++i) {
        for (size_t j = i + 1; j < strip.size() && (strip[j].y - strip[i].y) < delta; ++j) {
            min_dist = min(min_dist, dist(strip[i], strip[j]));
        }
    }

    return min_dist;
}

// Recursive function to find the closest pair in a set of points
long long closestUtil(const vector<Point>& points, size_t start, size_t end) {
    if (end - start <= 3) {
        long long min_dist = numeric_limits<long long>::max();
        for (size_t i = start; i < end; ++i) {
            for (size_t j = i + 1; j < end; ++j) {
                min_dist = min(min_dist, dist(points[i], points[j]));
            }
        }
        return min_dist;
    }

    size_t mid = (start + end) / 2;
    long long dl = closestUtil(points, start, mid);
    long long dr = closestUtil(points, mid, end);

    long long d = min(dl, dr);

    vector<Point> strip;
    for (size_t i = start; i < end; ++i) {
        if (abs(points[i].x - points[mid].x) < d) {
            strip.push_back(points[i]);
        }
    }

    return min(d, stripClosest(strip, d));
}

// Function to find the closest pair in a set of points
long long closestPair(const vector<Point>& points) {
    if (points.size() < 2) {
        return numeric_limits<long long>::max();
    }

    vector<Point> sorted_points = points;
    sort(sorted_points.begin(), sorted_points.end(), [](const Point& p1, const Point& p2) { return p1.x < p2.x; });

    return closestUtil(sorted_points, 0, points.size());
}

// --- End of Closest Pair of Points ---

