// --- build adjacency list ---
std::vector<std::vector<int>> adj;

// --- Tarjan's algorithm to find bridges and biconnected components ---
std::vector<int> disc, low, parent;
std::vector<bool> is_cut;
int time = 0;

void dfs(int u, int p) {
    disc[u] = low[u] = ++time;
    parent[u] = p;
    int children = 0;

    for (int v : adj[u]) {
        if (v == p) continue; // Skip parent edge
        if (disc[v] == -1) { // Tree edge
            children++;
            dfs(v, u);
            low[u] = std::min(low[u], low[v]);

            if (p == -1 && children > 1) is_cut[u] = true; // Root node with more than one child is a cut vertex
            if (p != -1 && low[v] >= disc[u]) is_cut[u] = true; // Non-root node with no back edge to ancestor
        } else { // Back edge
            low[u] = std::min(low[u], disc[v]);
        }
    }
}

// --- Build bridge tree ---
std::vector<int> bcc_id;
std::vector<std::vector<int>> bcc_tree;
int bcc_count = 0;

void build_bcc_tree(int u, int p) {
    bcc_id[u] = bcc_count;
    for (int v : adj[u]) {
        if (v == p || is_cut[v]) continue; // Skip parent and cut vertices
        if (bcc_id[v] == -1) { // New biconnected component
            bcc_count++;
            bcc_tree.push_back({u, v});
            build_bcc_tree(v, u);
        } else { // Existing biconnected component
            bcc_tree.push_back({bcc_id[u], bcc_id[v]});
        }
    }
}

// --- Entry point to build bridge tree ---
void build_bridge_tree(int n) {
    disc.assign(n, -1);
    low.assign(n, -1);
    parent.assign(n, -1);
    is_cut.assign(n, false);
    bcc_id.assign(n, -1);

    for (int i = 0; i < n; ++i) {
        if (disc[i] == -1) dfs(i, -1);
    }

    bcc_count = 0;
    build_bcc_tree(0, -1);
}

// --- LCA in bridge tree ---
std::vector<int> parent_bcc;

void build_parent_bcc(int u, int p) {
    parent_bcc[u] = p;
    for (int v : bcc_tree[u]) {
        if (v == p) continue;
        build_parent_bcc(v, u);
    }
}

int lca_bcc(int u, int v) {
    while (u != v) {
        if (parent_bcc[u] > parent_bcc[v]) std::swap(u, v);
        u = parent_bcc[u];
    }
    return u;
}

