// --- DSU with Small-to-Large Merging ---

struct DSU {
    vector<int> parent, size;

    // Constructor to initialize the DSU structure
    DSU(int n) : parent(n), size(n, 1) {
        iota(parent.begin(), parent.end(), 0); // Initialize parent array
    }

    // Find function with path compression
    int find(int u) {
        if (parent[u] != u)
            parent[u] = find(parent[u]); // Path compression
        return parent[u];
    }

    // Union function with small-to-large merging
    void merge(int u, int v) {
        int pu = find(u), pv = find(v);
        if (pu == pv)
            return; // Already in the same set

        if (size[pu] < size[pv])
            swap(pu, pv); // Ensure pu is the larger set

        parent[pv] = pu; // Attach smaller to larger
        size[pu] += size[pv]; // Update size of the new set
    }
};

// --- Usage Example ---

