// --- Sqrt Decomposition for Time Series Data ---

#include <vector>
#include <cmath>
#include <numeric>

// Time: O(n√n) — Space: O(n)
struct SqrtDecomposition {
    std::vector<long long> data;
    std::vector<long long> block_sums;
    int block_size;

    // Constructor to initialize the decomposition
    SqrtDecomposition(const std::vector<long long>& values) : data(values), block_size(std::sqrt(values.size())) {
        block_sums.resize((values.size() + block_size - 1) / block_size);
        for (int i = 0; i < values.size(); ++i) {
            block_sums[i / block_size] += values[i];
        }
    }

    // Update the value at index idx to new_val
    void update(int idx, long long new_val) {
        block_sums[idx / block_size] -= data[idx];
        data[idx] = new_val;
        block_sums[idx / block_size] += data[idx];
    }

    // Query the sum up to index idx
    long long query(int idx) const {
        long long sum = 0;
        for (int i = 0; i <= idx / block_size; ++i) {
            if (i == idx / block_size) {
                sum += std::accumulate(data.begin() + i * block_size, data.begin() + idx + 1, 0LL);
            } else {
                sum += block_sums[i];
            }
        }
        return sum;
    }
};

