// --- Garner's Algorithm Implementation ---

// Time: O(n) — Space: O(1)

#include <iostream>
#include <vector>
#include <numeric>

using namespace std;
typedef long long ll;

// Function to compute modular inverse using Extended Euclidean Algorithm
ll modInverse(ll a, ll m) {
    ll m0 = m, t, q;
    ll x0 = 0, x1 = 1;
    if (m == 1) return 0;
    while (a > 1) {
        q = a / m;
        t = m;
        m = a % m, a = t;
        t = x0;
        x0 = x1 - q * x0;
        x1 = t;
    }
    if (x1 < 0) x1 += m0;
    return x1;
}

// Function to solve system of congruences using Garner's Algorithm
ll garner(const vector<ll>& r, const vector<ll>& m) {
    ll x = r[0], M = m[0];
    for (size_t i = 1; i < r.size(); ++i) {
        ll Mi = M;
        M *= m[i];
        ll k = (r[i] - x * modInverse(Mi, m[i])) % m[i];
        if (k < 0) k += m[i];
        x += k * Mi;
    }
    return x % M;
}

// --- Usage Example ---

int main() {
    vector<ll> r = {3, 1, 2};
    vector<ll> m = {5, 7, 3};
    ll result = garner(r, m);
    cout << "X ≡ " << result << " mod " << accumulate(m.begin(), m.end(), 1LL, multiplies<ll>()) << endl;
    return 0;
}

