// --- Miller-Rabin Primality Test ---

#include <vector>
#include <random>
#include <cmath>

// Function to perform modular exponentiation
long long mod_pow(long long base, long long exp, long long mod) {
    long long result = 1;
    base = base % mod;
    while (exp > 0) {
        if (exp % 2 == 1)
            result = (result * base) % mod;
        exp = exp >> 1;
        base = (base * base) % mod;
    }
    return result;
}

// Function to perform the Miller-Rabin test for a single base
bool miller_rabin_test(long long n, long long d, int s, long long a) {
    long long x = mod_pow(a, d, n);
    if (x == 1 || x == n - 1)
        return true;
    for (int r = 1; r < s; ++r) {
        x = (x * x) % n;
        if (x == n - 1)
            return true;
    }
    return false;
}

// Main function to perform the Miller-Rabin primality test
bool is_prime(long long n, int k = 5) {
    if (n <= 1)
        return false;
    if (n <= 3)
        return true;
    if (n % 2 == 0 || n % 3 == 0)
        return false;

    long long d = n - 1;
    int s = 0;
    while (d % 2 == 0) {
        d /= 2;
        ++s;
    }

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(2, n - 2);

    for (int i = 0; i < k; ++i) {
        long long a = dis(gen);
        if (!miller_rabin_test(n, d, s, a))
            return false;
    }

    return true;
}

// --- Usage Example ---

#include <iostream>

int main() {
    long long n;
    std::cin >> n;
    if (is_prime(n))
        std::cout << "Prime\n";
    else
        std::cout << "Composite\n";
    return 0;
}

