// --- BSGS Algorithm for Discrete Logarithm ---

// Time: O(sqrt(n)) — Space: O(sqrt(n))

#include <vector>
#include <unordered_map>
#include <cmath>

using namespace std;

// Function to compute (base^exp) % mod using fast exponentiation
long long fastPower(long long base, long long exp, long long mod) {
    long long result = 1;
    base = base % mod;
    while (exp > 0) {
        if (exp % 2 == 1)
            result = (result * base) % mod;
        exp = exp >> 1;
        base = (base * base) % mod;
    }
    return result;
}

// Function to find the discrete logarithm using Baby-Step Giant-Step algorithm
long long discreteLog(long long g, long long h, long long p) {
    long long m = ceil(sqrt(p));
    unordered_map<long long, long long> table;

    // Precompute values of g^j for j in [0, m-1]
    for (long long j = 0; j < m; ++j)
        table[fastPower(g, j, p)] = j;

    // Compute h * g^{-im} for i from 0 to 1 and check against the precomputed values
    long long g_inv = fastPower(g, p - 2, p); // g^(-1) mod p
    for (long long i = 0; i <= m; ++i) {
        long long target = (h * fastPower(g_inv, i * m, p)) % p;
        if (table.find(target) != table.end())
            return i * m - table[target];
    }

    // If no solution found, return -1 (or throw an exception)
    return -1;
}

// --- Usage Example ---

// Input: g = 3, h = 5, p = 7
// Output: k = 2

int main() {
    long long g = 3, h = 5, p = 7;
    long long k = discreteLog(g, h, p);
    cout << "k = " << k << endl; // Output: k = 2
    return 0;
}

