// --- build adjacency list ---
std::vector<std::vector<int>> build_adjacency_list(const std::vector<int>& nums) {
    int n = nums.size();
    std::vector<std::vector<int>> adj(n);
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (nums[i] % nums[j] == 0 || nums[j] % nums[i] == 0) {
                adj[i].push_back(j);
                adj[j].push_back(i);
            }
        }
    }
    return adj;
}

// --- sieve of inclusion-exclusion ---
std::vector<int> sieve_inclusion_exclusion(const std::vector<int>& nums) {
    int n = nums.size();
    std::vector<int> result(n, 0);
    std::vector<std::vector<int>> adj = build_adjacency_list(nums);

    // --- count divisors for each number ---
    for (int i = 0; i < n; ++i) {
        for (int j : adj[i]) {
            result[i] += nums[j];
        }
    }

    // --- apply inclusion-exclusion principle ---
    for (int i = 0; i < n; ++i) {
        for (int j : adj[i]) {
            for (int k : adj[j]) {
                if (k != i && k != j) {
                    result[i] -= nums[k];
                }
            }
        }
    }

    return result;
}

