struct Edge {
    int to;
    int weight;
};

using Graph = std::vector<std::vector<Edge>>;

// --- Dial's Algorithm ---
long long dialAlgorithm(const Graph& graph, int source, int n) {
    std::vector<long long> dist(n, LLONG_MAX);
    dist[source] = 0;

    // --- bucket queue ---
    std::vector<std::queue<int>> buckets(n);
    buckets[0].push(source);

    while (!buckets.empty()) {
        int d = buckets.size() - 1;
        while (d >= 0 && buckets[d].empty()) {
            --d;
        }
        if (d < 0) break;

        int u = buckets[d].front();
        buckets[d].pop();

        for (const auto& edge : graph[u]) {
            int v = edge.to;
            int weight = edge.weight;

            if (dist[u] + weight < dist[v]) {
                dist[v] = dist[u] + weight;
                buckets[dist[v]].push(v);
            }
        }
    }

    return dist;
}

