using Graph = vector<vector<Edge>>;

// --- Johnson's Algorithm ---
vector<long long> johnson(const Graph& graph) {
    int n = graph.size();
    Graph newGraph(n + 1);
    for (int i = 0; i < n; ++i) {
        newGraph[n].push_back({i, 0}); // Add a new node with zero-weight edges to all others
    }
    newGraph.insert(newGraph.end(), graph.begin(), graph.end());

    // --- Bellman-Ford to compute potential values ---
    vector<long long> h(n + 1, 0);
    for (int k = 0; k < n; ++k) {
        for (int u = 0; u <= n; ++u) {
            for (const auto& e : newGraph[u]) {
                h[e.to] = min(h[e.to], h[u] + e.weight);
            }
        }
    }

    // --- Reweight the graph ---
    for (auto& edges : newGraph) {
        for (auto& e : edges) {
            e.weight += h[e.from] - h[e.to];
        }
    }

    // --- Dijkstra's algorithm from each node ---
    vector<vector<long long>> dist(n, vector<long long>(n, LLONG_MAX));
    for (int i = 0; i < n; ++i) {
        dist[i][i] = 0;
        priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;
        pq.push({0, i});
        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (d > dist[i][u]) continue;
            for (const auto& e : newGraph[u]) {
                long long newDist = d + e.weight;
                if (newDist < dist[i][e.to]) {
                    dist[i][e.to] = newDist;
                    pq.push({newDist, e.to});
                }
            }
        }
    }

    // --- Adjust distances back using the initial potentials ---
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            dist[i][j] -= h[i] - h[j];
        }
    }

    return dist;
}

