// --- parallel_binary_search ---

#include <vector>
#include <algorithm>
#include <execution>

// Time: O(log n * parallelism) — Space: O(1)
bool parallel_binary_search(const std::vector<int>& arr, int target) {
    auto lo = 0, hi = arr.size() - 1;
    while (lo <= hi) {
        auto mid = lo + (hi - lo) / 2;
        if (arr[mid] == target) return true;
        else if (arr[mid] < target) {
            // --- parallelize search in the right half ---
            auto it = std::lower_bound(std::execution::par_unseq, arr.begin() + mid + 1, arr.end(), target);
            if (it != arr.end() && *it == target) return true;
            hi = mid - 1;
        } else {
            // --- parallelize search in the left half ---
            auto it = std::upper_bound(std::execution::par_unseq, arr.begin(), arr.begin() + mid, target);
            if (it != arr.begin() && *(it - 1) == target) return true;
            lo = mid + 1;
        }
    }
    return false;
}

