// --- build adjacency list ---
std::vector<std::unordered_map<char, int>> build_automaton(const std::vector<std::string>& patterns) {
    int n = patterns.size();
    std::vector<std::unordered_map<char, int>> adj(n + 1);
    std::vector<int> fail(n + 1);

    // --- build trie ---
    for (int i = 0; i < n; ++i) {
        int u = 0;
        for (char c : patterns[i]) {
            if (!adj[u].count(c)) {
                adj[u][c] = adj.size();
                adj.push_back({});
            }
            u = adj[u][c];
        }
    }

    // --- build failure links ---
    std::queue<int> q;
    for (auto& [c, v] : adj[0]) {
        fail[v] = 0;
        q.push(v);
    }
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (auto& [c, v] : adj[u]) {
            int f = fail[u];
            while (f && !adj[f].count(c)) {
                f = fail[f];
            }
            fail[v] = adj[f][c];
            q.push(v);
        }
    }

    return adj;
}

// --- search text ---
std::vector<int> search(const std::string& text, const std::vector<std::string>& patterns) {
    auto adj = build_automaton(patterns);
    int n = adj.size();
    std::vector<int> result;
    int u = 0;

    for (int i = 0; i < text.size(); ++i) {
        while (u && !adj[u].count(text[i])) {
            u = fail[u];
        }
        if (adj[u].count(text[i])) {
            u = adj[u][text[i]];
            for (int j = 0; j < patterns.size(); ++j) {
                if (u == j + 1) {
                    result.push_back(i - patterns[j].size() + 1);
                }
            }
        }
    }

    return result;
}

