// --- build adjacency list ---
std::vector<std::unordered_map<char, int>> buildPatriciaTrie(const std::vector<std::string>& words) {
    int nodeCount = 1; // Root node
    std::vector<std::unordered_map<char, int>> trie(nodeCount);

    for (const auto& word : words) {
        int currentNode = 0;
        for (char c : word) {
            if (trie[currentNode].find(c) == trie[currentNode].end()) {
                trie.push_back({});
                trie[currentNode][c] = nodeCount++;
            }
            currentNode = trie[currentNode][c];
        }
    }

    return trie;
}

// --- find word in Patricia Trie ---
bool findWord(const std::vector<std::unordered_map<char, int>>& trie, const std::string& word) {
    int currentNode = 0;
    for (char c : word) {
        if (trie[currentNode].find(c) == trie[currentNode].end()) {
            return false;
        }
        currentNode = trie[currentNode][c];
    }
    return true;
}

// --- insert word into Patricia Trie ---
void insertWord(std::vector<std::unordered_map<char, int>>& trie, const std::string& word) {
    int currentNode = 0;
    for (char c : word) {
        if (trie[currentNode].find(c) == trie[currentNode].end()) {
            trie.push_back({});
            trie[currentNode][c] = trie.size() - 1;
        }
        currentNode = trie[currentNode][c];
    }
}

// --- delete word from Patricia Trie ---
void deleteWord(std::vector<std::unordered_map<char, int>>& trie, const std::string& word) {
    int currentNode = 0;
    for (char c : word) {
        if (trie[currentNode].find(c) == trie[currentNode].end()) {
            return; // Word not found
        }
        currentNode = trie[currentNode][c];
    }

    // Mark the end of the word
    trie[currentNode]['#'] = 1;
}

