// --- build failure automaton ---
std::vector<int> buildFailureAutomaton(const std::string& pattern) {
    int n = pattern.size();
    std::vector<int> failure(n, 0);
    for (int i = 1, j = 0; i < n; ++i) {
        while (j > 0 && pattern[i] != pattern[j]) j = failure[j - 1]; // --- find the longest prefix suffix ---
        if (pattern[i] == pattern[j]) ++j;
        failure[i] = j;
    }
    return failure;
}

// --- perform pattern matching using failure automaton ---
std::vector<int> kmpSearch(const std::string& text, const std::string& pattern) {
    int m = text.size(), n = pattern.size();
    std::vector<int> failure = buildFailureAutomaton(pattern);
    std::vector<int> matches;
    for (int i = 0, j = 0; i < m; ++i) {
        while (j > 0 && text[i] != pattern[j]) j = failure[j - 1]; // --- follow failure links ---
        if (text[i] == pattern[j]) ++j;
        if (j == n) { // --- full match found ---
            matches.push_back(i - j + 1);
            j = failure[j - 1]; // --- allow overlapping matches ---
        }
    }
    return matches;
}

