// --- Manacher's Algorithm ---

// Time: O(n) — Space: O(n)

#include <vector>
#include <string>
using namespace std;

vector<int> manacher(const string& s) {
    int n = s.size();
    vector<int> p(n, 0);
    int center = 0, right = 0;

    for (int i = 0; i < n; ++i) {
        // Mirror the current position around the center
        int mirror = center - (i - center);

        // If the current position is within the right boundary, use the mirrored value
        if (i < right) {
            p[i] = min(right - i, p[mirror]);
        }

        // Expand around the current position
        while (i + 1 + p[i] < n && i - 1 - p[i] >= 0 && s[i + 1 + p[i]] == s[i - 1 - p[i]]) {
            ++p[i];
        }

        // Update the center and right boundary if necessary
        if (i + p[i] > right) {
            center = i;
            right = i + p[i];
        }
    }

    return p;
}

