// --- Eertree Implementation ---

struct Eertree {
    vector<int> len, link, s;
    int n;

    // Constructor to initialize the Eertree with a given string
    Eertree(const string& str) : s(str), n(s.size()), len(n + 1), link(n + 1) {
        len[0] = -1; // Root node
        len[1] = 0; // First character node
        link[1] = 0;
        int j = 1;
        for (int i = 1; i < n; ++i) {
            while (j > 0 && s[i] != s[j + len[j]])
                j = link[j];
            if (s[i] == s[j + len[j]])
                j += len[j] + 1;
            len[i + 1] = j;
            link[i + 1] = link[j];
            while (j > 0 && s[i] != s[j + len[j]])
                j = link[j];
            if (s[i] == s[j + len[j]])
                j += len[j] + 1;
            link[i + 1] = j;
        }
    }

    // Function to get all palindromic substrings
    vector<string> getPalindromes() {
        vector<string> result;
        for (int i = 0; i < n; ++i) {
            int len_i = len[i];
            if (len_i > 0) {
                string palindrome = s.substr(i - len_i, len_i * 2 + 1);
                result.push_back(palindrome);
            }
        }
        return result;
    }
};

// --- Usage Example ---

int main() {
    string str = "aacecaaa";
    Eertree eertree(str);
    vector<string> palindromes = eertree.getPalindromes();
    for (const auto& palindrome : palindromes) {
        cout << palindrome << endl;
    }
    return 0;
}

