// --- build adjacency list ---
struct Edge {
    int u, v;
    long long w;
};

vector<vector<Edge>> build_adjacency_list(int n, vector<Edge>& edges) {
    vector<vector<Edge>> adj(n);
    for (auto& e : edges) {
        adj[e.u].push_back(e);
        adj[e.v].push_back({e.v, e.u, e.w}); // undirected graph
    }
    return adj;
}

// --- find parent with path compression ---
vector<int> parent;
int find(int u) {
    if (parent[u] != u)
        parent[u] = find(parent[u]); // path compression
    return parent[u];
}

// --- union by rank ---
vector<int> rank;
void union_sets(int u, int v) {
    int pu = find(u), pv = find(v);
    if (rank[pu] < rank[pv])
        parent[pu] = pv;
    else if (rank[pu] > rank[pv])
        parent[pv] = pu;
    else {
        parent[pv] = pu;
        rank[pu]++;
    }
}

// --- boruvka's algorithm ---
vector<Edge> boruvka_mst(int n, vector<Edge>& edges) {
    vector<Edge> mst;
    parent.resize(n);\    rank.resize(n, 0);
    for (int i = 0; i < n; ++i)
        parent[i] = i;

    while (mst.size() < n - 1) {
        vector<vector<Edge>> min_edges(n);
        for (auto& e : edges) {
            int pu = find(e.u), pv = find(e.v);
            if (pu != pv)
                min_edges[pu].push_back(e);
        }

        for (int i = 0; i < n; ++i) {
            if (!min_edges[i].empty()) {
                auto& e = *min_element(min_edges[i].begin(), min_edges[i].end(), [](const Edge& a, const Edge& b) {
                    return a.w < b.w;
                });
                mst.push_back(e);
                union_sets(e.u, e.v);
            }
        }
    }

    return mst;
}

// --- usage example ---
int main() {
    int n = 4;
    vector<Edge> edges = {{0, 1, 10}, {0, 2, 6}, {0, 3, 5}, {1, 3, 15}, {2, 3, 4}};
    auto mst = boruvka_mst(n, edges);
    for (auto& e : mst)
        cout << e.u << " -> " << e.v << " : " << e.w << endl;
    return 0;
}

