// --- build adjacency list ---
std::vector<std::vector<int>> build_adjacency_list(const std::vector<std::pair<int, int>>& edges, int n) {
    std::vector<std::vector<int>> adj(n + 1);
    for (const auto& [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    return adj;
}

// --- find centroid ---
int find_centroid(const std::vector<std::vector<int>>& adj, int node, int parent, int& size) {
    size = 1;
    for (const auto& neighbor : adj[node]) {
        if (neighbor != parent) {
            int subtree_size = find_centroid(adj, neighbor, node, size);
            size += subtree_size;
            if (subtree_size > size / 2) {
                return -1; // not a centroid
            }
        }
    }
    if (size > n / 2) {
        return -1; // not a centroid
    }
    return node;
}

// --- centroid decomposition ---
void centroid_decomposition(const std::vector<std::vector<int>>& adj, int node, int parent, std::vector<int>& centroid_nodes) {
    int size = 0;
    int centroid = find_centroid(adj, node, parent, size);
    if (centroid != -1) {
        centroid_nodes.push_back(centroid);
        for (const auto& neighbor : adj[centroid]) {
            if (neighbor != parent) {
                centroid_decomposition(adj, neighbor, centroid, centroid_nodes);
            }
        }
    }
}

// --- usage example ---
int main() {
    int n = 4;
    std::vector<std::pair<int, int>> edges = {{1, 2}, {2, 3}, {2, 4}};
    auto adj = build_adjacency_list(edges, n);
    std::vector<int> centroid_nodes;
    centroid_decomposition(adj, 1, -1, centroid_nodes);
    // Output centroid nodes
    for (int centroid : centroid_nodes) {
        std::cout << centroid << " ";
    }
    return 0;
}

