struct Node {
    vector<int> children;
};

vector<Node> build_adjacency_list(int n, vector<vector<int>>& edges) {
    vector<Node> adj(n);
    for (auto& e : edges) {
        adj[e[0]].children.push_back(e[1]);
        adj[e[1]].children.push_back(e[0]);
    }
    return adj;
}

// --- euler tour ---
vector<int> euler_tour;
vector<int> euler_pos;
int euler_time = 0;

void euler(int u, int p, vector<Node>& adj) {
    euler_tour.push_back(u);
    euler_pos[u] = euler_time++;
    for (auto v : adj[u]) {
        if (v != p) {
            euler(v, u, adj);
            euler_tour.push_back(u);
        }
    }
}

// --- heavy-light decomposition ---
vector<int> parent;
vector<int> head;
vector<int> depth;
vector<int> pos;
int hld_time = 0;

void dfs(int u, int p, int d, vector<Node>& adj) {
    parent[u] = p;
    depth[u] = d;
    pos[u] = hld_time++;
    for (auto v : adj[u]) {
        if (v != p) {
            dfs(v, u, d + 1, adj);
        }
    }
}

void decompose(int u, int h, vector<Node>& adj) {
    head[u] = h;
    for (auto v : adj[u]) {
        if (v != parent[u]) {
            if (depth[v] > depth[u]) {
                decompose(v, v, adj);
            } else {
                decompose(v, h, adj);
            }
        }
    }
}

// --- segment tree ---
struct SegmentTree {
    vector<long long> tree;
    int n;

    SegmentTree(int size) : n(size), tree(4 * size) {}

    void update(int p, long long val, int tl, int tr, int pos) {
        if (tl == tr) {
            tree[pos] = val;
        } else {
            int tm = (tl + tr) / 2;
            if (p <= tm) {
                update(p, val, tl, tm, 2 * pos);
            } else {
                update(p, val, tm + 1, tr, 2 * pos + 1);
            }
            tree[pos] = tree[2 * pos] + tree[2 * pos + 1];
        }
    }

    long long query(int l, int r, int tl, int tr, int pos) {
        if (l > r) return 0;
        if (l == tl && r == tr) return tree[pos];
        int tm = (tl + tr) / 2;
        return query(l, min(r, tm), tl, tm, 2 * pos) + query(max(l, tm + 1), r, tm + 1, tr, 2 * pos + 1);
    }
};

// --- hld queries ---
vector<long long> hld_query(int u, int v, SegmentTree& st) {
    vector<long long> result;
    while (head[u] != head[v]) {
        if (depth[head[u]] < depth[head[v]]) {
            swap(u, v);
        }
        result.push_back(st.query(pos[head[u]], pos[u], 0, n - 1, 1));
        u = parent[head[u]];
    }
    if (pos[u] > pos[v]) swap(u, v);
    result.push_back(st.query(pos[u], pos[v], 0, n - 1, 1));
    return result;
}

// --- hld updates ---
void hld_update(int u, long long val, SegmentTree& st) {
    st.update(pos[u], val, 0, n - 1, 1);
}

// --- complexity note ---
// Time: O(n log n) for preprocessing and O(log n) per query/update
// Space: O(n)

