// --- Kruskal's Tree (MST Structure) ---

#include <vector>
#include <algorithm>
#include <numeric>

// Time: O(E log E) — Space: O(V + E)
struct KruskalTree {
    int V, E;
    std::vector<std::pair<int, std::pair<int, int>>> edges;
    std::vector<int> parent, rank;

    KruskalTree(int V, int E) : V(V), E(E), edges(E), parent(V), rank(V, 0) {
        std::iota(parent.begin(), parent.end(), 0);
    }

    int find(int u) {
        if (parent[u] != u)
            parent[u] = find(parent[u]);
        return parent[u];
    }

    void unionSets(int u, int v) {
        int pu = find(u), pv = find(v);
        if (pu == pv) return;
        if (rank[pu] < rank[pv])
            std::swap(pu, pv);
        parent[pv] = pu;
        if (rank[pu] == rank[pv])
            ++rank[pu];
    }

    void addEdge(int u, int v, int w) {
        edges.push_back({w, {u, v}});
    }

    std::vector<std::pair<int, std::pair<int, int>>> kruskalMST() {
        std::sort(edges.begin(), edges.end());
        std::vector<std::pair<int, std::pair<int, int>>> mst;
        for (auto& edge : edges) {
            int u = edge.second.first, v = edge.second.second, w = edge.first;
            if (find(u) != find(v)) {
                unionSets(u, v);
                mst.push_back(edge);
            }
        }
        return mst;
    }
};

