std::vector<std::vector<int>> adj;

// --- euler tour and depth arrays ---
std::vector<int> euler, depths;
std::vector<int> in_time, out_time;
int timer = 0;

// --- dfs for euler tour ---
void dfs(int node, int parent, int depth) {
    in_time[node] = timer++;
    euler.push_back(node);
    depths.push_back(depth);
    for (int child : adj[node]) {
        if (child != parent) {
            dfs(child, node, depth + 1);
            euler.push_back(node);
            depths.push_back(depth);
        }
    }
    out_time[node] = timer++;
}

// --- sparse table for RMQ ---
std::vector<std::vector<int>> st;

// --- build sparse table ---
void build_sparse_table() {
    int n = euler.size();
    st.resize(n, std::vector<int>(32)); // assuming 32-bit depths
    for (int i = 0; i < n; ++i) {
        st[i][0] = depths[i];
    }
    for (int j = 1; (1 << j) <= n; ++j) {
        for (int i = 0; i + (1 << j) - 1 < n; ++i) {
            st[i][j] = std::max(st[i][j - 1], st[i + (1 << (j - 1))][j - 1]);
        }
    }
}

// --- query sparse table for RMQ ---
int query(int l, int r) {
    int k = std::floor(std::log2(r - l + 1));
    return std::max(st[l][k], st[r - (1 << k) + 1][k]);
}

// --- find LCA using Euler Tour and RMQ ---
int lca(int u, int v) {
    if (in_time[u] > in_time[v]) std::swap(u, v);
    return euler[query(in_time[u], out_time[v])];
}

