    --u, --v; // Convert to 0-based index
    adj[u].push_back(v);
    adj[v].push_back(u);
}

// --- rerooting function ---
std::vector<long long> reroot(int root) {
    std::vector<long long> dp(n, 0);
    std::stack<int> st;
    st.push(root);
    while (!st.empty()) {
        int u = st.top();
        st.pop();
        for (int v : adj[u]) {
            if (dp[v] != 0) continue; // Skip already processed nodes
            dp[v] = dp[u] + 1; // Update distance from root
            st.push(v);
        }
    }
    return dp;
}

// --- main function ---
int main() {
    int n;
    std::cin >> n;
    std::vector<long long> result = reroot(0); // Start rerooting from node 0
    for (long long dist : result) {
        std::cout << dist << ' ';
    }
    return 0;
}

