// --- Segment Tree Node ---
struct Node {
    long long sum; // Sum of the submatrix represented by this node
    Node(long long s = 0) : sum(s) {}
};

// --- 2D Segment Tree ---
class SegmentTree2D {
private:
    int n, m; // Dimensions of the grid
    vector<vector<Node>> tree; // 2D segment tree

    // Build the segment tree from the grid values
    void build(const vector<vector<long long>>& grid, int x, int y, int xn, int yn) {
        if (x == xn && y == yn) {
            tree[x][y] = Node(grid[x][y]);
            return;
        }
        int xm = (x + xn) / 2, ym = (y + yn) / 2;
        build(grid, x, y, xm, ym); // Top-left
        build(grid, x, ym + 1, xm, yn); // Top-right
        build(grid, xm + 1, y, xn, ym); // Bottom-left
        build(grid, xm + 1, ym + 1, xn, yn); // Bottom-right
        tree[x][y] = Node(tree[x][y].sum + tree[x][ym + 1].sum + tree[xm + 1][y].sum - tree[xm + 1][ym + 1].sum);
    }

    // Query the segment tree for the sum of the submatrix from (x1, y1) to (x2, y2)
    long long query(int x1, int y1, int x2, int y2, int x, int y, int xn, int yn) {
        if (x1 > x2 || y1 > y2) return 0; // Invalid query
        if (x1 == x && y1 == y && x2 == xn && y2 == yn) return tree[x][y].sum; // Exact match
        int xm = (x + xn) / 2, ym = (y + yn) / 2;
        long long res = 0;
        if (x1 <= xm && y1 <= ym) res += query(x1, y1, min(xm, x2), min(ym, y2), x, y, xm, ym);
        if (x1 <= xm && y2 > ym) res += query(x1, ym + 1, min(xm, x2), y2, x, ym + 1, xm, yn);
        if (x2 > xm && y1 <= ym) res += query(xm + 1, y1, x2, min(ym, y2), xm + 1, y, xn, ym);
        if (x2 > xm && y2 > ym) res += query(xm + 1, ym + 1, x2, y2, xm + 1, ym + 1, xn, yn);
        return res;
    }

public:
    // Constructor to initialize the segment tree with a grid
    SegmentTree2D(const vector<vector<long long>>& grid) {
        n = grid.size();
        m = grid[0].size();
        tree.resize(n, vector<Node>(m));
        build(grid, 0, 0, n - 1, m - 1);
    }

    // Function to query the sum of the submatrix from (x1, y1) to (x2, y2)
    long long query(int x1, int y1, int x2, int y2) {
        return query(x1, y1, x2, y2, 0, 0, n - 1, m - 1);
    }
};

