// --- build adjacency list ---
struct Node {
    int parent = -1;
    int heavy_child = -1;
    int size = 1;
    int depth = 0;
};

vector<Node> nodes;
vector<vector<int>> adj;

// --- splay tree operations ---
void rotate(int x) {
    int y = nodes[x].parent;
    int z = nodes[y].parent;
    if (nodes[y].heavy_child == x) nodes[y].heavy_child = nodes[x].heavy_child;
    if (z != -1) {
        if (nodes[z].heavy_child == y) nodes[z].heavy_child = x;
        else nodes[z].heavy_child = y;
    }
    nodes[x].parent = z;
    nodes[y].parent = x;
    nodes[nodes[x].heavy_child].parent = y;
    if (nodes[x].heavy_child != -1) nodes[nodes[x].heavy_child].depth = nodes[x].depth + 1;
    nodes[y].depth = nodes[x].depth + 1;
}

void splay(int x) {
    while (nodes[x].parent != -1) {
        int y = nodes[x].parent;
        int z = nodes[y].parent;
        if (z == -1) rotate(x);
        else if ((nodes[z].heavy_child == y) == (nodes[y].heavy_child == x)) rotate(y), rotate(x);
        else rotate(x), rotate(x);
    }
}

// --- link-cut tree operations ---
void cut(int x, int y) {
    splay(x);
    splay(y);
    nodes[x].parent = -1;
    nodes[y].heavy_child = -1;
}

void link(int x, int y) {
    splay(x);
    splay(y);
    nodes[x].parent = y;
    nodes[y].heavy_child = x;
}

// --- path queries ---
int find_root(int x) {
    splay(x);
    if (nodes[x].parent == -1) return x;
    else return find_root(nodes[x].parent);
}

bool is_connected(int x, int y) {
    return find_root(x) == find_root(y);
}

// --- complexity note ---
// Time: O(log n) for each operation (link, cut, find_root)
// Space: O(n) for storing nodes and adjacency list

