// --- mo's algorithm on trees ---
struct Query {
    int l, r, idx;
};

bool operator<(const Query& a, const Query& b) {
    if (a.l / sqrt(n) != b.l / sqrt(n)) return a.l < b.l;
    return a.r < b.r;
}

vector<int> mo_on_tree(int n, vector<pair<int, int>>& edges, vector<Query>& queries) {
    vector<Node> adj = build_adjacency_list(n, edges);
    dfs(0, 0, adj);

    vector<int> result(queries.size(), 0);
    vector<int> freq(n, 0);
    int left = 0, right = 0;

    for (Query& q : queries) {
        while (left < q.l) {
            // remove leftmost node from current segment
            int u = euler_tour[left++];
            freq[u]--;
        }
        while (right < q.r) {
            // add rightmost node to current segment
            int u = euler_tour[right++];
            freq[u]++;
        }
        while (left > q.l) {
            // remove leftmost node from current segment
            int u = euler_tour[--left];
            freq[u]--;
        }
        while (right > q.r) {
            // add rightmost node to current segment
            int u = euler_tour[--right];
            freq[u]++;
        }
        result[q.idx] = freq[euler_tour[left]];
    }

    return result;
}

