// --- dsu with rollback ---
struct DSU {
    std::vector<int> parent, rank;
    std::stack<std::pair<int, int>> history;

    DSU(int n) : parent(n), rank(n, 1) {
        std::iota(parent.begin(), parent.end(), 0);
    }

    int find(int u) {
        if (parent[u] != u) {
            parent[u] = find(parent[u]);
        }
        return parent[u];
    }

    void unite(int u, int v) {
        int pu = find(u), pv = find(v);
        if (pu == pv) return;
        if (rank[pu] < rank[pv]) {
            std::swap(pu, pv);
        }
        parent[pv] = pu;
        rank[pu] += rank[pv];
        history.push({pv, parent[pv]});
    }

    void rollback() {
        if (!history.empty()) {
            auto [u, v] = history.top();
            parent[u] = v;
            history.pop();
        }
    }
};

// --- mo's algorithm with rollback ---
std::vector<int> mo_algorithm_with_rollback(const std::vector<std::pair<int, int>>& queries, const std::vector<std::pair<int, int>>& edges, int n) {
    std::vector<int> result(queries.size(), 0);
    DSU dsu(n);

    // --- sort queries ---
    std::vector<std::tuple<int, int, int>> sorted_queries;
    for (int i = 0; i < queries.size(); ++i) {
        sorted_queries.emplace_back(queries[i].first, queries[i].second, i);
    }
    std::sort(sorted_queries.begin(), sorted_queries.end(), [&](const auto& a, const auto& b) {
        int l1 = a.first / 200, r1 = a.second / 200;
        int l2 = b.first / 200, r2 = b.second / 200;
        if (l1 != l2) return l1 < l2;
        if (r1 != r2) return r1 < r2;
        return a.second < b.second;
    });

    // --- process queries ---
    int left = 0, right = 0;
    for (const auto& [l, r, idx] : sorted_queries) {
        while (left < l) {
            dsu.unite(queries[left].first, queries[left].second);
            ++left;
        }
        while (right < r) {
            dsu.unite(queries[right].first, queries[right].second);
            ++right;
        }
        while (left > l) {
            dsu.rollback();
            --left;
        }
        while (right > r) {
            dsu.rollback();
            --right;
        }
        result[idx] = dsu.find(queries[idx].first) == dsu.find(queries[idx].second);
    }

    return result;
}

