// --- build adjacency list ---
std::vector<std::vector<int>> adj(n);

// --- LCT node structure ---
struct Node {
    int parent, child[2]; // child[0] is left, child[1] is right
    int size; // subtree size
    bool rev; // reverse flag for lazy propagation
};
Node nodes[n];

// --- LCT functions ---
void push(int u) {
    if (nodes[u].rev) {
        std::swap(nodes[u].child[0], nodes[u].child[1]);
        nodes[nodes[u].child[0]].rev ^= 1;
        nodes[nodes[u].child[1]].rev ^= 1;
        nodes[u].rev = false;
    }
}

void pull(int u) {
    nodes[u].size = 1;
    for (int i = 0; i < 2; ++i) {
        if (nodes[u].child[i] != -1) {
            push(nodes[u].child[i]);
            nodes[u].size += nodes[nodes[u].child[i]].size;
        }
    }
}

void rotate(int u, int dir) {
    int p = nodes[u].parent, g = nodes[p].parent;
    int c = nodes[u].child[!dir];
    nodes[u].child[!dir] = p;
    nodes[p].parent = u;
    nodes[p].child[dir] = c;
    if (c != -1) nodes[c].parent = p;
    nodes[u].parent = g;
    if (g != -1) {
        nodes[g].child[nodes[g].child[1] == p] = u;
    }
    pull(p);
    pull(u);
}

void splay(int u) {
    while (nodes[u].parent != -1) {
        int p = nodes[u].parent, g = nodes[p].parent;
        if (g == -1) {
            rotate(u, nodes[u].child[0] == p);
        } else {
            int dir1 = nodes[p].child[0] == u, dir2 = nodes[g].child[0] == p;
            if (dir1 == dir2) {
                rotate(p, dir1);
                rotate(u, dir1);
            } else {
                rotate(u, dir1);
                rotate(u, dir2);
            }
        }
    }
}

int find_root(int u) {
    splay(u);
    if (nodes[u].child[0] != -1) {
        push(nodes[u].child[0]);
        splay(nodes[u].child[0]);
        nodes[u].child[0] = -1;
        pull(u);
    }
    return u;
}

void link(int u, int v) {
    splay(u);
    splay(v);
    if (find_root(u) == find_root(v)) return;
    nodes[u].parent = v;
    nodes[v].child[1] = u;
    pull(v);
}

void cut(int u, int v) {
    splay(u);
    splay(v);
    if (nodes[v].child[0] != u) return;
    nodes[v].child[0] = -1;
    nodes[u].parent = -1;
    pull(v);
}

bool connected(int u, int v) {
    splay(u);
    splay(v);
    return find_root(u) == find_root(v);
}

// --- main function ---
void process_queries(const std::vector<std::tuple<int, int, bool>>& queries) {
    for (const auto& [u, v, is_add] : queries) {
        if (is_add) {
            link(u, v);
        } else {
            cut(u, v);
        }
    }
}

// --- usage example ---
int main() {
    int n = 4; // number of nodes
    std::vector<std::tuple<int, int, bool>> queries = {
        {0, 1, true}, // add edge between 0 and 1
        {0, 2, true}, // add edge between 0 and 2
        {0, 1, false}, // remove edge between 0 and 1
        {0, 1, true}  // add edge between 0 and 1 again
    };
    process_queries(queries);
    return 0;
}

