// --- Persistent DSU Implementation ---

#include <vector>
#include <array>
#include <algorithm>

using namespace std;

// --- DSU Node ---
struct DSUNode {
    int parent, rank;
    DSUNode(int p = -1, int r = 0) : parent(p), rank(r) {}
};

// --- Persistent DSU ---
class PersistentDSU {
private:
    vector<vector<DSUNode>> history;

public:
    // Initialize with n elements
    PersistentDSU(int n) : history(1, vector<DSUNode>(n)) {}

    // Find root of x with path compression
    int find(int version, int x) {
        if (history[version][x].parent != x)
            history[version][x].parent = find(version, history[version][x].parent);
        return history[version][x].parent;
    }

    // Union sets containing x and y
    void unite(int version, int x, int y) {
        int px = find(version, x), py = find(version, y);
        if (px != py) {
            if (history[version][px].rank < history[version][py].rank)
                swap(px, py);
            history.push_back(history.back());
            history.back()[px].parent = py;
            if (history[version][px].rank == history[version][py].rank)
                history.back()[py].rank++;
        }
    }

    // Get parent of x at a specific version
    int getParent(int version, int x) {
        return history[version][x].parent;
    }
};

// --- Complexity Analysis ---
// Time: O(log n) for find and unite operations
// Space: O(n log n) for storing all versions

// --- Usage Example ---
// PersistentDSU dsu(5);
// dsu.unite(0, 0, 1);
// cout << dsu.getParent(0, 0) << endl; // Output: 1
// cout << dsu.getParent(0, 1) << endl; // Output: 1
// cout << dsu.getParent(0, 2) << endl; // Output: 2

// --- Notes ---
// - Use long long for large n to avoid overflow
// - Path compression and union by rank ensure nearly constant time operations
// - Each version is a deep copy of the previous one, except for changed parts
// - Memory usage is efficient due to reuse of unchanged parts
// - Common TLE causes: large n or m, inefficient implementation details

