// --- Persistent Segment Tree Implementation ---

#include <vector>
#include <algorithm>

using namespace std;

struct Node {
    int val; // Value at this node
    Node* left, *right; // Left and right children
    Node(int v) : val(v), left(nullptr), right(nullptr) {}
};

Node* build(const vector<int>& arr, int l, int r) {
    if (l > r) return nullptr; // Base case: invalid range
    if (l == r) return new Node(arr[l]); // Base case: single element
    int m = (l + r) / 2;
    Node* root = new Node(0); // Create a new node
    root->left = build(arr, l, m); // Build left subtree
    root->right = build(arr, m + 1, r); // Build right subtree
    return root;
}

Node* update(Node* root, int l, int r, int idx, int val) {
    if (l > r || idx < l || idx > r) return root; // Base case: invalid range or out of bounds
    if (l == r) return new Node(val); // Base case: single element
    int m = (l + r) / 2;
    Node* newRoot = new Node(0); // Create a new node
    newRoot->left = update(root->left, l, m, idx, val); // Update left subtree
    newRoot->right = update(root->right, m + 1, r, idx, val); // Update right subtree
    newRoot->val = newRoot->left->val + newRoot->right->val; // Recalculate value
    return newRoot;
}

int query(Node* root, int l, int r, int ql, int qr) {
    if (l > r || ql > r || qr < l) return 0; // Base case: invalid range or out of bounds
    if (ql <= l && r <= qr) return root->val; // Base case: complete overlap
    int m = (l + r) / 2;
    return query(root->left, l, m, ql, qr) + query(root->right, m + 1, r, ql, qr); // Query both subtrees
}

// --- Complexity Analysis ---
// Time: O(log n) for each update and query operation
// Space: O(n log n) for storing all nodes

