// --- Segment Tree Beats Implementation ---

// Time: O(log n) per operation
// Space: O(n)

#include <vector>
#include <algorithm>

using namespace std;

struct SegmentTreeBeats {
    int n;
    vector<int> tree;
    vector<int> lazy;

    // --- Constructor ---
    SegmentTreeBeats(int size) : n(size), tree(4 * size, 0), lazy(4 * size, 0) {}

    // --- Build Segment Tree ---
    void build(const vector<int>& arr, int node, int start, int end) {
        if (start == end) {
            tree[node] = arr[start];
        } else {
            int mid = (start + end) / 2;
            build(arr, 2 * node, start, mid);
            build(arr, 2 * node + 1, mid + 1, end);
            tree[node] = min(tree[2 * node], tree[2 * node + 1]); // Example: Range Minimum
        }
    }

    // --- Lazy Update ---
    void updateLazy(int node, int start, int end, int l, int r, int val) {
        if (lazy[node] != 0) {
            tree[node] = lazy[node];
            if (start != end) {
                lazy[2 * node] = lazy[node];
                lazy[2 * node + 1] = lazy[node];
            }
            lazy[node] = 0;
        }

        if (start > end || start > r || end < l) return;

        if (start >= l && end <= r) {
            tree[node] = val;
            if (start != end) {
                lazy[2 * node] = val;
                lazy[2 * node + 1] = val;
            }
            return;
        }

        int mid = (start + end) / 2;
        updateLazy(2 * node, start, mid, l, r, val);
        updateLazy(2 * node + 1, mid + 1, end, l, r, val);
        tree[node] = min(tree[2 * node], tree[2 * node + 1]); // Example: Range Minimum
    }

    // --- Query ---
    int query(int node, int start, int end, int l, int r) {
        if (lazy[node] != 0) {
            tree[node] = lazy[node];
            if (start != end) {
                lazy[2 * node] = lazy[node];
                lazy[2 * node + 1] = lazy[node];
            }
            lazy[node] = 0;
        }

        if (start > end || start > r || end < l) return INT_MAX; // Example: Range Minimum

        if (start >= l && end <= r) return tree[node];

        int mid = (start + end) / 2;
        int left = query(2 * node, start, mid, l, r);
        int right = query(2 * node + 1, mid + 1, end, l, r);
        return min(left, right); // Example: Range Minimum
    }
};

