// --- Splay Tree Implementation ---

// Node structure for the splay tree
struct Node {
    int key;
    Node* left;
    Node* right;
    Node(int k) : key(k), left(nullptr), right(nullptr) {}
};

// --- Splay Tree Class ---
class SplayTree {
public:
    Node* root;

    SplayTree() : root(nullptr) {}

    // --- Splay Operation ---
    void splay(Node* x) {
        while (x != root) {
            Node* p = x->parent;
            if (p == root) {
                // Zig
                if (x == p->left) {
                    rightRotate(p);
                } else {
                    leftRotate(p);
                }
            } else {
                Node* g = p->parent;
                if ((x == p->left) == (p == g->left)) {
                    // Zig-Zig
                    if (x == p->left) {
                        rightRotate(g);
                        rightRotate(p);
                    } else {
                        leftRotate(g);
                        leftRotate(p);
                    }
                } else {
                    // Zig-Zag
                    if (x == p->left) {
                        rightRotate(p);
                        leftRotate(g);
                    } else {
                        leftRotate(p);
                        rightRotate(g);
                    }
                }
            }
        }
    }

    // --- Left Rotate ---
    void leftRotate(Node* x) {
        Node* y = x->right;
        x->right = y->left;
        if (y->left != nullptr) {
            y->left->parent = x;
        }
        y->parent = x->parent;
        if (x->parent == nullptr) {
            root = y;
        } else if (x == x->parent->left) {
            x->parent->left = y;
        } else {
            x->parent->right = y;
        }
        y->left = x;
        x->parent = y;
    }

    // --- Right Rotate ---
    void rightRotate(Node* x) {
        Node* y = x->left;
        x->left = y->right;
        if (y->right != nullptr) {
            y->right->parent = x;
        }
        y->parent = x->parent;
        if (x->parent == nullptr) {
            root = y;
        } else if (x == x->parent->right) {
            x->parent->right = y;
        } else {
            x->parent->left = y;
        }
        y->right = x;
        x->parent = y;
    }

    // --- Insert Operation ---
    void insert(int key) {
        Node* z = new Node(key);
        Node* y = nullptr;
        Node* x = root;

        while (x != nullptr) {
            y = x;
            if (z->key < x->key) {
                x = x->left;
            } else {
                x = x->right;
            }
        }
        z->parent = y;
        if (y == nullptr) {
            root = z;
        } else if (z->key < y->key) {
            y->left = z;
        } else {
            y->right = z;
        }

        splay(z);
    }

    // --- Search Operation ---
    Node* search(int key) {
        Node* x = root;
        while (x != nullptr && x->key != key) {
            if (key < x->key) {
                x = x->left;
            } else {
                x = x->right;
            }
        }
        if (x != nullptr) {
            splay(x);
        }
        return x;
    }

    // --- Delete Operation ---
    void deleteNode(int key) {
        Node* z = search(key);
        if (z == nullptr) {
            return;
        }

        splay(z);

        Node* leftSubtree = z->left;
        Node* rightSubtree = z->right;

        if (leftSubtree != nullptr) {
            leftSubtree->parent = nullptr;
            root = leftSubtree;
            splay(leftSubtree);
            leftSubtree->right = rightSubtree;
            if (rightSubtree != nullptr) {
                rightSubtree->parent = leftSubtree;
            }
        } else {
            root = rightSubtree;
            if (rightSubtree != nullptr) {
                rightSubtree->parent = nullptr;
            }
        }

        delete z;
    }
};

// --- Complexity Analysis ---
// Time: O(log n) for search, insert, and delete operations on average due to splay property.
// Space: O(n) for storing n nodes in the tree.

// --- Usage Example ---
// SplayTree st;
// st.insert(10);
// st.insert(20);
// st.insert(30);
// Node* node = st.search(20);
// if (node != nullptr) {
//     cout << "Found: " << node->key << endl;
// }
// st.deleteNode(20);

// --- Implementation Notes ---
// - Splay trees are self-adjusting binary search trees that move recently accessed elements to the root.
// - The splay operation ensures that the most recently accessed element is always at the root, making future accesses faster.
// - The amortized time complexity of operations is O(log n) due to the splay property.
// - Splay trees are useful in scenarios where there are frequent access patterns and locality of reference.
// - Common TLE causes include large input sizes or inefficient implementation details.
// - Memory layout tips include careful management of pointers and avoiding unnecessary allocations.
// - C++ specific gotchas include signed/unsigned comparisons and iterator invalidation during rotations.

