// --- Sqrt Tree Implementation ---

#include <vector>
#include <cmath>
#include <numeric>

// --- Sqrt Tree Class ---
class SqrtTree {
public:
    SqrtTree(const std::vector<int>& arr) : n(arr.size()), block_size(std::ceil(std::sqrt(n))), tree(n * 2, 0) {
        // --- Build the Sqrt Tree ---
        for (int i = 0; i < n; ++i) {
            update(i, arr[i]);
        }
    }

    int query(int l, int r) {
        // --- Query the range [l, r] ---
        int sum = 0;
        while (l <= r) {
            if (l % block_size == 0 && r % block_size == block_size - 1) {
                // Full block
                sum += std::accumulate(tree.begin() + l, tree.begin() + r + 1, 0);
                break;
            } else if (l % block_size == 0) {
                // Left partial block
                sum += std::accumulate(tree.begin() + l, tree.begin() + (l / block_size + 1) * block_size, 0);
                l = (l / block_size + 1) * block_size;
            } else if (r % block_size == block_size - 1) {
                // Right partial block
                sum += std::accumulate(tree.begin() + r / block_size * block_size, tree.begin() + r + 1, 0);
                r = r / block_size * block_size - 1;
            } else {
                // Both partial blocks
                sum += arr[l] + arr[r];
                ++l;
                --r;
            }
        }
        return sum;
    }

    void update(int idx, int val) {
        // --- Update the value at index idx ---
        int block = idx / block_size;
        tree[idx] += val - arr[idx];
        arr[idx] = val;
        for (int i = idx; i > 0; i /= 2) {
            tree[i] = tree[i * 2] + tree[i * 2 + 1];
        }
    }

private:
    int n, block_size;
    std::vector<int> arr, tree;
};

