// --- Van Emde Boas Tree Implementation ---

// Time: O(log M) per operation
// Space: O(sqrt(M))

#include <vector>
#include <cmath>

using namespace std;

struct VEBTree {
    int u; // universe size
    int min_val, max_val;
    VEBTree* summary;
    vector<VEBTree*> cluster;

    VEBTree(int _u) : u(_u), min_val(-1), max_val(-1) {
        if (u == 2) {
            summary = nullptr;
            cluster = {nullptr, nullptr};
        } else {
            int s = sqrt(u);
            summary = new VEBTree(s);
            cluster.resize(s, nullptr);
            for (int i = 0; i < s; ++i) {
                cluster[i] = new VEBTree(u / s);
            }
        }
    }

    ~VEBTree() {
        if (u > 2) {
            delete summary;
            for (int i = 0; i < cluster.size(); ++i) {
                delete cluster[i];
            }
        }
    }

    int high(int x) { return x / sqrt(u); }
    int low(int x) { return x % sqrt(u); }
    int index(int high, int low) { return high * sqrt(u) + low; }

    void insert(int x) {
        if (min_val == -1) {
            min_val = max_val = x;
        } else if (x < min_val) {
            swap(x, min_val);
        }
        if (u > 2) {
            int h = high(x);
            if (cluster[h]->min_val == -1) {
                summary->insert(h);
                cluster[h]->insert(low(x));
                max_val = max(max_val, x);
            } else {
                cluster[h]->insert(low(x));
                max_val = max(max_val, x);
            }
        }
    }

    bool member(int x) {
        if (x == min_val || x == max_val) {
            return true;
        }
        if (u > 2) {
            int h = high(x);
            if (cluster[h]->member(low(x))) {
                return true;
            }
        }
        return false;
    }

    int successor(int x) {
        if (u == 2) {
            if (x == 0 && max_val == 1) {
                return 1;
            } else {
                return -1;
            }
        } else {
            if (min_val != -1 && x < min_val) {
                return min_val;
            }
            int h = high(x);
            int t = cluster[h]->successor(low(x));
            if (t != -1) {
                return index(h, t);
            } else {
                int s = summary->successor(h);
                if (s == -1) {
                    return -1;
                } else {
                    t = cluster[s]->min_val;
                    return index(s, t);
                }
            }
        }
    }

    int predecessor(int x) {
        if (u == 2) {
            if (x == 1 && min_val == 0) {
                return 0;
            } else {
                return -1;
            }
        } else {
            if (max_val != -1 && x > max_val) {
                return max_val;
            }
            int h = high(x);
            int t = cluster[h]->predecessor(low(x));
            if (t != -1) {
                return index(h, t);
            } else {
                int s = summary->predecessor(h);
                if (s == -1) {
                    return -1;
                } else {
                    t = cluster[s]->max_val;
                    return index(s, t);
                }
            }
        }
    }
};

