// --- Wavelet Tree Implementation ---

// Time: O(n log n) — Space: O(n log n)

#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

struct WaveletTree {
    vector<vector<int>> tree;
    vector<int> prefix;
    int n, max_depth;

    // --- Build the wavelet tree ---
    WaveletTree(vector<int>& arr) : n(arr.size()), max_depth(ceil(log2(n))) {
        tree.resize(max_depth + 1);
        prefix.resize(max_depth + 1);
        build(arr, 0, n - 1, 0);
    }

    // --- Build the wavelet tree recursively ---
    void build(vector<int>& arr, int l, int r, int depth) {
        if (l > r) return;
        if (l == r) {
            tree[depth].push_back(arr[l]);
            prefix[depth] = 1;
            return;
        }

        int mid = (l + r) / 2;
        int median = kth_smallest(arr, l, r, (r - l + 1) / 2);

        vector<int> left, right;
        for (int i = l; i <= r; ++i) {
            if (arr[i] <= median) {
                left.push_back(arr[i]);
            } else {
                right.push_back(arr[i]);
            }
        }

        tree[depth].insert(tree[depth].end(), left.begin(), left.end());
        tree[depth].insert(tree[depth].end(), right.begin(), right.end());

        prefix[depth] = left.size();

        build(left, l, mid, depth + 1);
        build(right, mid + 1, r, depth + 1);
    }

    // --- Find the k-th smallest element in a range ---
    int kth_smallest(vector<int>& arr, int l, int r, int k) {
        if (l > r) return -1;
        if (l == r) return arr[l];

        int mid = (l + r) / 2;
        int left_count = prefix[0] - (mid - l + 1);

        if (k <= left_count) {
            return kth_smallest(arr, l, mid, k);
        } else {
            return kth_smallest(arr, mid + 1, r, k - left_count);
        }
    }

    // --- Count elements in a range less than or equal to x ---
    int count_le(vector<int>& arr, int l, int r, int x) {
        if (l > r) return 0;
        if (x < arr[l]) return 0;
        if (x >= arr[r]) return r - l + 1;

        int mid = (l + r) / 2;
        int left_count = prefix[0] - (mid - l + 1);

        if (x <= arr[mid]) {
            return count_le(arr, l, mid, x);
        } else {
            return left_count + count_le(arr, mid + 1, r, x);
        }
    }
};

