// --- D-ary Heap Implementation ---

// Time: O(log_d n) for extract-min and heapify
// Space: O(n)

#include <vector>
#include <algorithm>

struct DaryHeap {
    int d; // Number of children per node
    std::vector<int> heap;

    DaryHeap(int d) : d(d), heap(1, INT_MAX) {}

    void insert(int key) {
        heap.push_back(key);
        siftUp(heap.size() - 1);
    }

    int extractMin() {
        if (heap.size() == 1) return INT_MAX;
        int min = heap[1];
        heap[1] = heap.back();
        heap.pop_back();
        siftDown(1);
        return min;
    }

private:
    void siftUp(int i) {
        while (i > 1 && heap[parent(i)] > heap[i]) {
            std::swap(heap[parent(i)], heap[i]);
            i = parent(i);
        }
    }

    void siftDown(int i) {
        int minIndex = i;
        for (int j = 1; j <= d; ++j) {
            int child = i * d + j;
            if (child < heap.size() && heap[child] < heap[minIndex]) {
                minIndex = child;
            }
        }
        if (minIndex != i) {
            std::swap(heap[i], heap[minIndex]);
            siftDown(minIndex);
        }
    }

    int parent(int i) { return i / d; }
};

// --- Fibonacci Heap Implementation ---

// Time: O(log n) for extract-min and decrease-key
// Space: O(n)

struct Node {
    int key;
    Node* child;
    Node* left;
    Node* right;
    int degree;
    bool mark;

    Node(int k) : key(k), child(nullptr), left(this), right(this), degree(0), mark(false) {}
};

struct FibonacciHeap {
    Node* min;
    int size;

    FibonacciHeap() : min(nullptr), size(0) {}

    void insert(int key) {
        Node* node = new Node(key);
        if (min == nullptr) {
            min = node;
        } else {
            min->right->left = node;
            node->right = min->right;
            min->right = node;
            node->left = min;
            if (key < min->key) {
                min = node;
            }
        }
        size++;
    }

    int extractMin() {
        if (min == nullptr) return INT_MAX;
        Node* z = min;
        for (Node* x = z->child; x != nullptr; x = x->right) {
            x->parent = nullptr;
        }
        if (z == z->right) {
            min = nullptr;
        } else {
            min->left->right = z->right;
            z->right->left = z->left;
            min = z->right;
            consolidate();
        }
        size--;
        return z->key;
    }

private:
    void consolidate() {
        std::vector<Node*> A(size + 1, nullptr);
        for (Node* w = min; w != nullptr; w = w->right) {
            Node* x = w;
            while (A[x->degree] != nullptr) {
                Node* y = A[x->degree];
                if (x->key > y->key) {
                    std::swap(x, y);
                }
                link(y, x);
                A[x->degree] = nullptr;
                x->degree++;
            }
            A[x->degree] = x;
        }
        min = nullptr;
        for (int i = 0; i <= size; ++i) {
            if (A[i] != nullptr) {
                A[i]->left = A[i]->right = A[i];
                if (min == nullptr) {
                    min = A[i];
                } else {
                    min->right->left = A[i];
                    A[i]->right = min->right;
                    min->right = A[i];
                    A[i]->left = min;
                    if (A[i]->key < min->key) {
                        min = A[i];
                    }
                }
            }
        }
    }

    void link(Node* y, Node* x) {
        y->right->left = y->left;
        y->left->right = y->right;
        if (x->child == nullptr) {
            x->child = y;
            y->left = y->right = y;
        } else {
            y->left = x->child;
            y->right = x->child->right;
            x->child->right->left = y;
            x->child->right = y;
        }
        y->parent = x;
        y->mark = false;
        x->degree++;
    }
};

