// --- Skip List Implementation ---

#include <vector>
#include <cstdlib>
#include <ctime>

// --- Node Definition ---
struct Node {
    int value;
    std::vector<Node*> forward;
    Node(int val) : value(val), forward(1, nullptr) {}
};

// --- Skip List Class ---
class SkipList {
private:
    Node* head;
    int maxLevel;
    float p;

    // --- Generate a random level for a new node ---
    int randomLevel() {
        int lvl = 1;
        while (lvl < maxLevel && ((double)rand() / RAND_MAX) < p)
            lvl++;
        return lvl;
    }

public:
    SkipList(int maxLvl, float prob) : maxLevel(maxLvl), p(prob) {
        head = new Node(INT_MIN);
        for (int i = 0; i < maxLevel; ++i)
            head->forward[i] = nullptr;
    }

    ~SkipList() {
        delete head;
    }

    // --- Search for a value in the Skip List ---
    bool search(int value) {
        Node* x = head;
        for (int i = maxLevel - 1; i >= 0; --i) {
            while (x->forward[i] != nullptr && x->forward[i]->value < value)
                x = x->forward[i];
        }
        if (x->forward[0] != nullptr && x->forward[0]->value == value)
            return true;
        return false;
    }

    // --- Insert a value into the Skip List ---
    void insert(int value) {
        std::vector<Node*> update(maxLevel, head);
        Node* x = head;
        for (int i = maxLevel - 1; i >= 0; --i) {
            while (x->forward[i] != nullptr && x->forward[i]->value < value)
                x = x->forward[i];
            update[i] = x;
        }
        int lvl = randomLevel();
        if (lvl > maxLevel) {
            for (int i = maxLevel; i < lvl; ++i)
                update[i] = head;
            maxLevel = lvl;
        }
        Node* newNode = new Node(value);
        newNode->forward.resize(lvl);
        for (int i = 0; i < lvl; ++i) {
            newNode->forward[i] = update[i]->forward[i];
            update[i]->forward[i] = newNode;
        }
    }

    // --- Delete a value from the Skip List ---
    void erase(int value) {
        std::vector<Node*> update(maxLevel, nullptr);
        Node* x = head;
        for (int i = maxLevel - 1; i >= 0; --i) {
            while (x->forward[i] != nullptr && x->forward[i]->value < value)
                x = x->forward[i];
            update[i] = x;
        }
        if (x->forward[0] != nullptr && x->forward[0]->value == value) {
            for (int i = 0; i < maxLevel; ++i) {
                if (update[i]->forward[i] != x)
                    break;
                update[i]->forward[i] = x->forward[i];
            }
            delete x;
        }
    }
};

// --- Complexity Note ---
// Time: O(log n) for search, insert, and delete operations
// Space: O(n log n) due to the multiple layers of pointers

