// --- WQS Binary Search Implementation ---

#include <vector>
#include <algorithm>
#include <functional>

// Time: O(n log n) — Space: O(n)

using namespace std;

struct WQSBinarySearch {
    vector<long long> a;
    function<long long(long long)> cost;

    WQSBinarySearch(vector<long long>& _a, function<long long(long long)> _cost) : a(_a), cost(_cost) {}

    long long solve() {
        int n = a.size();
        long long left = 0, right = 1e9;

        // --- Binary search for the optimal parameter ---
        while (left < right) {
            long long mid = (left + right) / 2;
            if (isFeasible(mid)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        return left;
    }

private:
    bool isFeasible(long long param) {
        // --- Use convex hull trick to check feasibility ---
        vector<pair<long long, long long>> hull;
        for (int i = 0; i < a.size(); ++i) {
            while (hull.size() >= 2 && hull[hull.size() - 2].second * (a[i] - hull.back().first) >= hull.back().second * (a[i] - hull[hull.size() - 2].first)) {
                hull.pop_back();
            }
            hull.push_back({a[i], cost(param) - param * a[i]});
        }

        return hull.back().second <= 0;
    }
};

