std::vector<std::vector<int>> build_adjacency_list(const std::vector<std::vector<int>>& cost_matrix) {
    int n = cost_matrix.size();
    std::vector<std::vector<int>> adj(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            adj[i].push_back(cost_matrix[i][j]);
        }
    }
    return adj;
}

// --- reduce costs ---
void reduce_costs(std::vector<std::vector<int>>& cost_matrix) {
    int n = cost_matrix.size();
    for (int i = 0; i < n; ++i) {
        int min_row = *std::min_element(cost_matrix[i].begin(), cost_matrix[i].end());
        for (int j = 0; j < n; ++j) {
            cost_matrix[i][j] -= min_row;
        }
    }
    for (int j = 0; j < n; ++j) {
        int min_col = *std::min_element(cost_matrix.begin(), cost_matrix.end(), [j](const auto& a, const auto& b) { return a[j] < b[j]; });
        for (int i = 0; i < n; ++i) {
            cost_matrix[i][j] -= min_col;
        }
    }
}

// --- find augmenting path ---
bool find_augmenting_path(const std::vector<std::vector<int>>& cost_matrix, std::vector<bool>& visited, int u, std::vector<int>& parent) {
    int n = cost_matrix.size();
    for (int v = 0; v < n; ++v) {
        if (!visited[v] && cost_matrix[u][v] == 0) {
            visited[v] = true;
            if (parent[v] == -1 || find_augmenting_path(cost_matrix, visited, parent[v], parent)) {
                parent[v] = u;
                return true;
            }
        }
    }
    return false;
}

// --- hungarian algorithm ---
int hungarian_algorithm(const std::vector<std::vector<int>>& cost_matrix) {
    int n = cost_matrix.size();
    std::vector<int> parent(n, -1);
    std::vector<bool> visited(n, false);
    int max_matching = 0;

    for (int u = 0; u < n; ++u) {
        std::fill(visited.begin(), visited.end(), false);
        if (find_augmenting_path(cost_matrix, visited, u, parent)) {
            ++max_matching;
        }
    }

    return max_matching;
}

