// --- blossom algorithm ---
std::vector<int> parent(n, -1);
std::vector<int> blossom(n, -1);
std::vector<bool> visited(n, false);

int find(int u) {
    if (parent[u] == -1) return u;
    if (blossom[parent[u]] != -1) {
        int p = parent[u];
        while (p != blossom[p]) {
            parent[p] = blossom[p];
            p = parent[p];
        }
    }
    return parent[u];
}

void augment(int s, int t) {
    std::vector<int> path;
    for (int u = t; u != s; u = parent[u]) {
        path.push_back(u);
    }
    path.push_back(s);
    std::reverse(path.begin(), path.end());

    for (size_t i = 0; i < path.size(); i += 2) {
        parent[path[i]] = path[i + 1];
        parent[path[i + 1]] = path[i];
    }
}

bool blossom_shrink(int u, int v) {
    std::vector<int> blossom_nodes;
    int pu = find(u), pv = find(v);
    if (pu == pv) return false;

    for (int x = u; x != pu; x = parent[x]) {
        blossom_nodes.push_back(x);
        blossom[x] = pu;
    }
    for (int x = v; x != pv; x = parent[x]) {
        blossom_nodes.push_back(x);
        blossom[x] = pv;
    }

    for (auto x : blossom_nodes) {
        visited[x] = false;
    }

    return true;
}

int max_matching() {
    int matching = 0;
    for (int u = 0; u < n; ++u) {
        if (parent[u] == -1) {
            for (int v : adj[u]) {
                if (parent[v] == -1 && blossom_shrink(u, v)) {
                    augment(u, v);
                    matching++;
                }
            }
        }
    }
    return matching;
}

