// --- build adjacency list ---
std::vector<std::vector<int>> build_adjacency_list(const std::vector<std::pair<int, int>>& edges, int n) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    return adj;
}

// --- matroid intersection algorithm ---
std::vector<int> matroid_intersection(const std::vector<std::vector<int>>& adj, const std::vector<int>& capacities1, const std::vector<int>& capacities2) {
    int n = adj.size();
    std::vector<int> common_set(n, 0);

    // --- initialize with any common independent set ---
    for (int i = 0; i < n; ++i) {
        if (capacities1[i] > 0 && capacities2[i] > 0) {
            common_set[i] = 1;
        }
    }

    // --- improve the solution iteratively ---
    bool improved;
    do {
        improved = false;
        for (int i = 0; i < n; ++i) {
            if (common_set[i] == 0) {
                int gain1 = 0, gain2 = 0;
                for (int j : adj[i]) {
                    if (common_set[j] == 1) {
                        gain1 += capacities1[i] - capacities1[j];
                        gain2 += capacities2[i] - capacities2[j];
                    }
                }
                if (gain1 > 0 && gain2 > 0) {
                    common_set[i] = 1;
                    improved = true;
                }
            }
        }
    } while (improved);

    return common_set;
}

// --- usage example ---
int main() {
    int n = 4;
    std::vector<std::pair<int, int>> edges = {{0, 1}, {1, 2}, {2, 3}, {3, 0}};
    std::vector<int> capacities1 = {1, 2, 3, 4};
    std::vector<int> capacities2 = {4, 3, 2, 1};

    auto adj = build_adjacency_list(edges, n);
    auto result = matroid_intersection(adj, capacities1, capacities2);

    for (int i : result) {
        std::cout << i << " ";
    }
    return 0;
}

