// --- build adjacency list ---
struct Edge {
    int to, capacity, cost;
    int rev; // index of reverse edge
};

struct MinCostMaxFlow {
    vector<vector<Edge>> adj;
    vector<long long> dist;
    vector<int> prev;
    int n;

    MinCostMaxFlow(int n) : n(n), adj(n) {}

    void addEdge(int from, int to, int capacity, int cost) {
        Edge forward = {to, capacity, cost, (int)adj[to].size()};
        Edge backward = {from, 0, -cost, (int)adj[from].size()};
        adj[from].push_back(forward);
        adj[to].push_back(backward);
    }

    // --- dijkstra's algorithm for min cost flow ---
    long long minCostFlow(int s, int t, long long f) {
        long long total_cost = 0;
        while (f > 0) {
            dist.assign(n, LLONG_MAX);
            dist[s] = 0;
            vector<int> in_queue(n, false);
            queue<int> q;
            q.push(s);
            in_queue[s] = true;

            // --- spfa to find shortest path ---
            while (!q.empty()) {
                int u = q.front();
                q.pop();
                in_queue[u] = false;

                for (auto& e : adj[u]) {
                    if (e.capacity > 0 && dist[u] + e.cost < dist[e.to]) {
                        dist[e.to] = dist[u] + e.cost;
                        prev[e.to] = u;
                        prev_index[e.to] = e.rev;
                        if (!in_queue[e.to]) {
                            q.push(e.to);
                            in_queue[e.to] = true;
                        }
                    }
                }
            }

            if (dist[t] == LLONG_MAX) break; // no augmenting path

            // --- find max flow on the path ---
            long long d = f;
            for (int v = t; v != s; v = prev[v]) {
                d = min(d, adj[prev[v]][prev_index[v]].capacity);
            }

            // --- update capacities and costs ---
            for (int v = t; v != s; v = prev[v]) {
                Edge& e = adj[prev[v]][prev_index[v]];
                e.capacity -= d;
                adj[v][e.rev].capacity += d;
                total_cost += d * e.cost;
            }

            f -= d;
        }
        return total_cost;
    }
};

