// --- build adjacency list ---
struct Edge {
    int to, capacity;
};

using Graph = vector<vector<Edge>>;

// --- Ford-Fulkerson with BFS for min-cut ---
long long bfsMaxFlow(Graph& g, int s, int t, vector<int>& parent) {
    int n = g.size();
    vector<bool> visited(n, false);
    queue<int> q;
    q.push(s);
    visited[s] = true;

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        for (const auto& e : g[u]) {
            if (!visited[e.to] && e.capacity > 0) {
                parent[e.to] = u;
                visited[e.to] = true;
                q.push(e.to);
                if (e.to == t) return e.capacity;
            }
        }
    }

    return 0;
}

long long edmondsKarp(Graph& g, int s, int t) {
    int n = g.size();
    vector<int> parent(n);
    long long maxFlow = 0;

    while (true) {
        long long flow = bfsMaxFlow(g, s, t, parent);
        if (flow == 0) break;

        maxFlow += flow;
        int v = t;

        while (v != s) {
            int u = parent[v];
            for (auto& e : g[u]) {
                if (e.to == v) {
                    e.capacity -= flow;
                    break;
                }
            }
            for (auto& e : g[v]) {
                if (e.to == u) {
                    e.capacity += flow;
                    break;
                }
            }
            v = u;
        }
    }

    return maxFlow;
}

// --- build project selection graph ---
Graph buildProjectSelectionGraph(const vector<pair<int, int>>& projects, const vector<pair<int, int>>& resources) {
    int n = projects.size();
    int m = resources.size();
    int s = 0, t = n + m + 1;
    Graph g(t + 1);

    // source to projects
    for (int i = 0; i < n; ++i) {
        g[s].emplace_back(i + 1, projects[i].first);
    }

    // projects to resources
    for (int i = 0; i < n; ++i) {
        int projectResource = projects[i].second;
        g[i + 1].emplace_back(n + projectResource, INT_MAX);
    }

    // resources to sink
    for (int i = 0; i < m; ++i) {
        g[n + i + 1].emplace_back(t, resources[i].second);
    }

    return g;
}

// --- solve project selection problem ---
long long solveProjectSelection(const vector<pair<int, int>>& projects, const vector<pair<int, int>>& resources) {
    Graph g = buildProjectSelectionGraph(projects, resources);
    return edmondsKarp(g, 0, g.size() - 1);
}

