// --- build adjacency list ---
struct Edge {
    int to, cap, flow;
    Edge(int to, int cap, int flow) : to(to), cap(cap), flow(flow) {}
};

using Graph = vector<vector<Edge>>;
using Flow = long long;

// --- push-relabel algorithm ---
Flow pushRelabel(Graph& g, int s, int t, int n) {
    vector<Flow> excess(n, 0);
    vector<int> height(n, 0), active(n, false);
    queue<int> q;

    // Initialize preflow
    for (auto& e : g[s]) {
        e.flow = e.cap;
        excess[e.to] += e.flow;
        if (e.flow > 0) {
            height[e.to] = height[s] + 1;
            q.push(e.to);
        }
    }

    // --- relabel function ---
    auto relabel = [&](int u) {
        int new_height = n;
        for (auto& e : g[u]) {
            if (e.flow < e.cap && height[u] > height[e.to]) {
                new_height = min(new_height, height[e.to] + 1);
            }
        }
        if (new_height < n) {
            height[u] = new_height;
        }
    };

    // --- push function ---
    auto push = [&](int u, int v) {
        Flow flow = min(excess[u], g[u][v].cap - g[u][v].flow);
        g[u][v].flow += flow;
        g[v][u].flow -= flow;
        excess[u] -= flow;
        excess[v] += flow;
        if (excess[v] > 0 && !active[v]) {
            active[v] = true;
            q.push(v);
        }
    };

    // --- main loop ---
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        active[u] = false;

        bool pushed = false;
        for (auto& e : g[u]) {
            if (e.flow < e.cap && height[u] > height[e.to]) {
                push(u, e.to);
                pushed = true;
            }
        }

        if (!pushed) {
            relabel(u);
        }
    }

    // Sum up the flow from the source to the sink
    Flow maxFlow = 0;
    for (auto& e : g[s]) {
        maxFlow += e.flow;
    }
    return maxFlow;
}

