// Alpha-Beta Pruning function
int alphaBetaPrune(vector<vector<int>>& board, int depth, bool isMaximizing, int alpha, int beta) {
    // Base case: evaluate leaf node
    if (depth == 0) {
        return evaluateNode(board);
    }

    // Maximizing player
    if (isMaximizing) {
        for (int i = 0; i < board.size(); ++i) {
            for (int j = 0; j < board[i].size(); ++j) {
                if (board[i][j] == 0) { // Assuming 0 means an empty cell
                    board[i][j] = 1; // Player makes a move
                    int value = alphaBetaPrune(board, depth - 1, false, alpha, beta);
                    board[i][j] = 0; // Undo move
                    alpha = max(alpha, value);
                    if (alpha >= beta) {
                        return beta; // Beta cut-off
                    }
                }
            }
        }
        return alpha;
    } else { // Minimizing player
        for (int i = 0; i < board.size(); ++i) {
            for (int j = 0; j < board[i].size(); ++j) {
                if (board[i][j] == 0) { // Assuming 0 means an empty cell
                    board[i][j] = -1; // Opponent makes a move
                    int value = alphaBetaPrune(board, depth - 1, true, alpha, beta);
                    board[i][j] = 0; // Undo move
                    beta = min(beta, value);
                    if (alpha >= beta) {
                        return alpha; // Alpha cut-off
                    }
                }
            }
        }
        return beta;
    }
}

