// --- build adjacency list ---
std::vector<std::vector<int>> build_adjacency_list(const std::vector<std::pair<int, int>>& edges) {
    int n = 0;
    for (const auto& [u, v] : edges) {
        n = std::max(n, std::max(u, v));
    }
    n++;
    std::vector<std::vector<int>> adj(n);
    for (const auto& [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    return adj;
}

// --- calculate Grundy number for a component ---
long long grundy_number(const std::vector<std::vector<int>>& adj, int node, std::vector<bool>& visited) {
    visited[node] = true;
    std::vector<long long> subgrundy;
    for (int neighbor : adj[node]) {
        if (!visited[neighbor]) {
            subgrundy.push_back(grundy_number(adj, neighbor, visited));
        }
    }
    return subgrundy.empty() ? 0 : std::accumulate(subgrundy.begin(), subgrundy.end(), 0LL, [](long long a, long long b) { return a ^ b; });
}

// --- calculate total Grundy number for the graph ---
long long total_grundy_number(const std::vector<std::pair<int, int>>& edges) {
    std::vector<std::vector<int>> adj = build_adjacency_list(edges);
    int n = adj.size();
    std::vector<bool> visited(n, false);
    return grundy_number(adj, 0, visited);
}

