// --- Misère Nim Solution ---

#include <vector>
#include <numeric>
#include <algorithm>

// Function to determine if the player to move is in a winning position
bool misereNim(const std::vector<int>& piles) {
    // Calculate XOR of all pile sizes
    long long xorSum = std::accumulate(piles.begin(), piles.end(), 0LL, [](long long x, int y) { return x ^ y; });

    // Count the number of piles with size 1
    int countOnes = std::count_if(piles.begin(), piles.end(), [](int x) { return x == 1; });

    // If there's exactly one pile of size 1, adjust by taking from the largest pile
    if (countOnes == 1) {
        int maxPile = *std::max_element(piles.begin(), piles.end());
        xorSum ^= maxPile;
    }

    // If the XOR is non-zero, the player to move is in a winning position
    return xorSum != 0;
}

// --- End of Misère Nim Solution ---

