// --- Time Complexity: O(n log n) for sorting + O(n) for processing each line
// --- Space Complexity: O(n) for storing lines and intersections

#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;
typedef long long ll;
typedef pair<ll, ll> Point;
typedef pair<Point, Point> Line;

double cross(const Point& a, const Point& b) {
    return a.first * b.second - a.second * b.first;
}

bool cmp(const Line& l1, const Line& l2) {
    return cross(l1.first, l2.first) > 0;
}

vector<Point> halfPlaneIntersection(vector<Line>& lines) {
    sort(lines.begin(), lines.end(), cmp);
    vector<Point> intersections;
    vector<Line> active;

    for (const auto& line : lines) {
        while (active.size() >= 2 && cross(active[active.size() - 2].second, line.first) <= 0) {
            active.pop_back();
        }
        if (!active.empty()) {
            intersections.push_back(intersection(active.back().first, active.back().second, line.first));
        }
        active.push_back(line);
    }

    while (active.size() >= 2 && cross(active[active.size() - 2].second, active[0].first) <= 0) {
        active.pop_back();
    }
    if (active.size() >= 2) {
        intersections.push_back(intersection(active.back().first, active.back().second, active[0].first));
    }

    return intersections;
}

Point intersection(const Point& p1, const Point& q1, const Point& p2) {
    ll dx1 = q1.first - p1.first, dy1 = q1.second - p1.second;
    ll dx2 = p2.first - p1.first, dy2 = p2.second - p1.second;
    ll det = dx1 * dy2 - dy1 * dx2;
    return {p1.first + dx1 * (p2.second - p1.second) / det, p1.second + dy1 * (p2.first - p1.first) / det};
}

