#include <algorithm>
#include <cmath>

using namespace std;
typedef long long ll;
typedef pair<ll, ll> Point;

// Function to compute the convex hull using Andrew's monotone chain algorithm
vector<Point> convexHull(vector<Point>& points) {
    sort(points.begin(), points.end());
    vector<Point> lower, upper;
    for (auto& p : points) {
        while (lower.size() >= 2 && cross(lower[lower.size() - 2], lower.back(), p) <= 0) {
            lower.pop_back();
        }
        lower.push_back(p);
    }
    for (int i = points.size() - 1; i >= 0; --i) {
        while (upper.size() >= 2 && cross(upper[upper.size() - 2], upper.back(), points[i]) <= 0) {
            upper.pop_back();
        }
        upper.push_back(points[i]);
    }
    lower.pop_back(); // Remove the last point as it's repeated
    return vector<Point>(lower.begin(), upper.end());
}

// Function to compute the cross product of vectors AB and AC
ll cross(const Point& A, const Point& B, const Point& C) {
    return (B.first - A.first) * (C.second - A.second) - (B.second - A.second) * (C.first - A.first);
}

// Function to compute the Minkowski sum of two convex polygons
vector<Point> minkowskiSum(const vector<Point>& A, const vector<Point>& B) {
    vector<Point> hullA = convexHull(A);
    vector<Point> hullB = convexHull(B);
    int n = hullA.size(), m = hullB.size();
    vector<Point> result;
    for (int i = 0, j = 0; i < n || j < m;) {
        Point p1 = hullA[i], p2 = hullB[j];
        if (p1.first + p2.first > p2.first + hullA[(i + 1) % n].first) {
            result.push_back(p1 + p2);
            i = (i + 1) % n;
        } else {
            result.push_back(p1 + p2);
            j = (j + 1) % m;
        }
    }
    return result;
}

