// --- build adjacency list ---
std::vector<std::vector<int>> build_adjacency_list(const std::vector<std::pair<long long, long long>>& points) {
    int n = points.size();
    std::vector<std::vector<int>> adj(n);
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (is_delaunay(points[i], points[j])) {
                adj[i].push_back(j);
                adj[j].push_back(i);
            }
        }
    }
    return adj;
}

// --- check if two points form a Delaunay edge ---
bool is_delaunay(const std::pair<long long, long long>& p1, const std::pair<long long, long long>& p2) {
    // Check if no other point lies inside the circumcircle of (p1, p2)
    for (const auto& p : points) {
        if (p != p1 && p != p2 && is_inside_circumcircle(p1, p2, p)) {
            return false;
        }
    }
    return true;
}

// --- check if a point lies inside the circumcircle of three points ---
bool is_inside_circumcircle(const std::pair<long long, long long>& p1, const std::pair<long long, long long>& p2, const std::pair<long long, long long>& p3) {
    // Use determinant method to check if point is inside circumcircle
    long long det = (p1.first * p1.first + p1.second * p1.second) * (p2.second - p3.second) +
                    (p2.first * p2.first + p2.second * p2.second) * (p3.second - p1.second) +
                    (p3.first * p3.first + p3.second * p3.second) * (p1.second - p2.second);
    return det > 0;
}

