        adj[u].emplace_back(v, w);
        adj[v].emplace_back(u, w);
    }
    return adj;
}

// --- find minimum spanning tree using Kruskal's algorithm ---
std::vector<std::tuple<int, int, int>> kruskal_mst(int n, std::vector<std::tuple<int, int, int>>& edges) {
    std::sort(edges.begin(), edges.end(), [](const auto& a, const auto& b) {
        return std::get<2>(a) < std::get<2>(b);
    });

    std::vector<int> parent(n), rank(n, 0);
    for (int i = 0; i < n; ++i) parent[i] = i;

    auto find = [&](int u) {
        if (parent[u] != u) parent[u] = find(parent[u]);
        return parent[u];
    };

    auto union_set = [&](int u, int v) {
        int pu = find(u), pv = find(v);
        if (pu == pv) return false;
        if (rank[pu] > rank[pv]) parent[pv] = pu;
        else if (rank[pu] < rank[pv]) parent[pu] = pv;
        else {
            parent[pv] = pu;
            ++rank[pu];
        }
        return true;
    };

    std::vector<std::tuple<int, int, int>> mst;
    for (const auto& [u, v, w] : edges) {
        if (union_set(u, v)) {
            mst.emplace_back(u, v, w);
        }
    }
    return mst;
}

// --- greedy algorithm to find maximum independent set in a matroid ---
std::vector<int> max_independent_set(int n, std::vector<std::vector<int>>& edges) {
    std::vector<int> independent_set;
    std::vector<bool> included(n, false);

    for (int i = 0; i < n; ++i) {
        bool can_add = true;
        for (const auto& neighbor : edges[i]) {
            if (included[neighbor]) {
                can_add = false;
                break;
            }
        }
        if (can_add) {
            independent_set.push_back(i);
            included[i] = true;
        }
    }

    return independent_set;
}

