// --- Berlekamp-Massey Algorithm ---

#include <vector>
#include <algorithm>

// Time: O(n^2) — Space: O(n)
std::vector<int> berlekampMassey(const std::vector<int>& sequence) {
    int n = sequence.size();
    std::vector<int> c(n), b(n), t(n);
    int l = 0, m = -1;
    int mu = 0, p = 0;

    for (int i = 0; i < n; ++i) {
        int d = sequence[i];
        for (int j = 1; j <= l; ++j)
            d ^= c[j] * sequence[i - j];

        if (d == 0) {
            p += 1;
        } else {
            if (m == -1) {
                m = i;
                std::copy(c.begin(), c.end(), b.begin());
                l = i + 1;
                mu = i;
            } else {
                int temp = i - m;
                for (int j = 0; j < n; ++j)
                    t[j] = c[j];

                for (int j = 0; j <= l; ++j)
                    c[j] = c[j] ^ b[j] * d;

                if (temp > mu) {
                    mu = temp;
                    std::copy(c.begin(), c.end(), b.begin());
                    l = i + 1;
                } else {
                    for (int j = temp; j <= l; ++j)
                        b[j] = b[j] ^ c[j - temp] * d;

                    l -= temp;
                }
            }
            p = i + 1;
        }
    }

    std::vector<int> result(l + 1);
    for (int i = 0; i <= l; ++i)
        result[i] = c[l - i];

    return result;
}

