// --- Dirichlet Series & Lucy_Hedgehog Sieve ---

// Time: O(n log n) — Space: O(n)

#include <vector>
#include <cmath>

using namespace std;

// Function to compute the Dirichlet series for a multiplicative function f
vector<long long> dirichlet_series(const vector<long long>& f, int n) {
    vector<long long> result(n + 1, 0);
    result[1] = f[1]; // Base case: f(1) = 1

    for (int p = 2; p <= n; ++p) {
        if (f[p] == 0) continue; // Skip non-prime numbers

        // Update the result for multiples of p
        for (int k = p; k <= n; k += p) {
            result[k] += f[p] * result[k / p];
        }
    }

    return result;
}

// --- Example usage ---

