    vector<long long> f = {0, 3, 1, 4, 1, 5};
    int n = 5;
    vector<long long> result = dirichlet_series(f, n);

    for (int i = 1; i <= n; ++i) {
        cout << result[i] << " ";
    }

    return 0;
}

