// --- FFT Implementation ---

#include <vector>
#include <complex>
#include <cmath>

using namespace std;
typedef complex<double> cpx;

// --- Helper Functions ---

// Bit-reversal permutation
void bitReverse(vector<cpx>& a) {
    int n = a.size();
    for (int i = 1, j = n / 2; i < n - 1; i++) {
        if (i < j) swap(a[i], a[j]);
        int m = n / 2;
        while (j >= m) j -= m, m /= 2;
        j += m;
    }
}

// FFT function
void fft(vector<cpx>& a, bool inv) {
    int n = a.size();
    bitReverse(a);
    for (int len = 2; len <= n; len <<= 1) {
        double ang = 2 * M_PI / len * (inv ? -1 : 1);
        cpx wlen(cos(ang), sin(ang));
        for (int i = 0; i < n; i += len) {
            cpx w(1);
            for (int j = 0; j < len / 2; j++) {
                cpx u = a[i + j], v = a[i + j + len / 2] * w;
                a[i + j] = u + v;
                a[i + j + len / 2] = u - v;
                w *= wlen;
            }
        }
    }
    if (inv) {
        for (cpx& x : a) x /= n;
    }
}

// --- Polynomial Multiplication using FFT ---

vector<long long> multiplyPolynomials(const vector<long long>& A, const vector<long long>& B) {
    int n = 1;
    while (n < A.size() + B.size()) n <<= 1;
    vector<cpx> a(n), b(n);
    for (int i = 0; i < A.size(); i++) a[i] = A[i];
    for (int i = 0; i < B.size(); i++) b[i] = B[i];
    fft(a, false);
    fft(b, false);
    for (int i = 0; i < n; i++) a[i] *= b[i];
    fft(a, true);
    vector<long long> res(n);
    for (int i = 0; i < n; i++) res[i] = round(a[i].real());
    return res;
}

