// --- Fast Walsh-Hadamard Transform ---
void fwht(vector<long long>& a, bool inverse) {
    int n = a.size();
    for (int len = 2; len <= n; len <<= 1) {
        for (int i = 0; i < n; i += len) {
            for (int j = 0; j < len / 2; ++j) {
                long long u = a[i + j];
                long long v = a[i + j + len / 2];
                if (inverse) {
                    a[i + j] = (u - v + n) % n;
                    a[i + j + len / 2] = (u + v) % n;
                } else {
                    a[i + j] = u ^ v;
                    a[i + j + len / 2] = u ^ (~v);
                }
            }
        }
    }
}

