// --- Min-25 Sieve Implementation ---

#include <vector>
#include <cmath>

// Time: O(n log log n) — Space: O(n)
std::vector<long long> min25_sieve(long long n) {
    std::vector<long long> phi(n + 1);
    for (long long i = 1; i <= n; ++i) phi[i] = i; // Initialize phi[k] = k

    // --- Sieve primes and update totient values ---
    for (long long p = 2; p * p <= n; ++p) {
        if (phi[p] == p) { // p is prime
            for (long long m = p * p; m <= n; m += p) {
                if (m % (p * p) == 0) phi[m] -= phi[m / p]; // m is divisible by p^2
                else phi[m] -= phi[p] * phi[m / p] / p; // m is divisible by p but not p^2
            }
        }
    }

    return phi;
}

