// --- Multiplicative Functions & Dirichlet Convolution ---

// Time: O(n log n) — Space: O(n)

#include <vector>
#include <numeric>
#include <iostream>

using namespace std;
typedef long long ll;

// Function to compute Euler's totient function φ(n)
vector<ll> euler_totient(int n) {
    vector<ll> phi(n + 1);
    iota(phi.begin(), phi.end(), 0); // Initialize phi[i] = i
    for (int p = 2; p <= n; ++p) {
        if (phi[p] == p) { // p is prime
            for (int i = p; i <= n; i += p) {
                phi[i] -= phi[i] / p; // Update multiples of p
            }
        }
    }
    return phi;
}

// Function to compute the Möbius function μ(n)
vector<ll> mobius(int n) {
    vector<ll> mu(n + 1, 1);
    for (int p = 2; p <= n; ++p) {
        if (mu[p] == 1) { // p is prime
            for (int i = p; i <= n; i += p) {
                mu[i] *= -1; // Update multiples of p
                if (i % (p * p) == 0) {
                    mu[i] = 0; // Reset to 0 if p^2 divides i
                }
            }
        }
    }
    return mu;
}

// Function to compute the Dirichlet convolution of two functions f and g
vector<ll> dirichlet_convolution(const vector<ll>& f, const vector<ll>& g) {
    int n = f.size();
    vector<ll> result(n);
    for (int i = 1; i < n; ++i) {
        for (int j = 1; j * i < n; ++j) {
            result[i * j] += f[j] * g[i]; // Convolution formula
        }
    }
    return result;
}

