// --- Multipoint Evaluation using FFT ---

#include <vector>
#include <complex>
#include <cmath>

using namespace std;
typedef complex<double> cd;

// Helper function to perform FFT on a vector of complex numbers
void fft(vector<cd>& a, bool invert) {
    int n = a.size();
    for (int len = 2; len <= n; len <<= 1) {
        double ang = 2 * M_PI / len * (invert ? -1 : 1);
        cd wlen(cos(ang), sin(ang));
        for (int i = 0; i < n; i += len) {
            cd w(1);
            for (int j = 0; j < len / 2; ++j) {
                cd u = a[i + j], v = a[i + j + len / 2] * w;
                a[i + j] = u + v;
                a[i + j + len / 2] = u - v;
                w *= wlen;
            }
        }
    }
    if (invert)
        for (cd& x : a)
            x /= n;
}

// Function to evaluate polynomial P(x) at points a1, a2, ..., an using FFT
vector<long long> multipointEvaluation(const vector<long long>& coeffs, const vector<long long>& points) {
    int n = points.size(), m = coeffs.size();
    vector<cd> fa(m), fb(n);
    for (int i = 0; i < m; ++i)
        fa[i] = coeffs[m - 1 - i];
    for (int i = 0; i < n; ++i)
        fb[i] = points[n - 1 - i];

    fft(fa, false);
    fft(fb, false);

    for (int i = 0; i < n; ++i)
        fa[i] *= fb[i];

    fft(fa, true);

    vector<long long> result(n);
    for (int i = 0; i < n; ++i)
        result[i] = round(fa[i].real());

    return result;
}

// --- Interpolation using Lagrange Interpolation ---

// Function to perform Lagrange interpolation to find the polynomial passing through given points
vector<long long> lagrangeInterpolation(const vector<long long>& x, const vector<long long>& y) {
    int n = x.size();
    vector<long long> result(n);
    for (int i = 0; i < n; ++i) {
        long long term = 1;
        for (int j = 0; j < n; ++j) {
            if (i != j) {
                term *= x[i] - x[j];
                term /= x[i] - x[j];
            }
        }
        result[i] = y[i] * term;
    }
    return result;
}

// --- Example Usage ---

// int main() {
//     vector<long long> coeffs = {3, 2, 1}; // Coefficients of P(x) = x^2 + 2x + 3
