// --- Möbius Function & Inversion Implementation ---

// Time: O(n log n) — Space: O(n)

#include <vector>
#include <cmath>

using namespace std;
typedef long long ll;

// Function to compute the Möbius function for all numbers up to n
vector<int> mobius(int n) {
    vector<int> mu(n + 1, 1); // Initialize Möbius function with 1s
    vector<int> primeCount(n + 1, 0); // Count of prime factors

    // Sieve to compute the Möbius function
    for (int i = 2; i <= n; ++i) {
        if (primeCount[i] == 0) { // i is prime
            for (int j = i; j <= n; j += i) {
                primeCount[j]++; // Increment prime factor count
                if (primeCount[j] % 2 == 0) {
                    mu[j] = 1; // If even number of prime factors, μ(i) = 1
                } else {
                    mu[j] = -1; // If odd number of prime factors, μ(i) = -1
                }
            }
        }
    }
    return mu;
}

// Function to perform Möbius inversion on a given function f
vector<ll> mobiusInversion(const vector<ll>& f, const vector<int>& mu) {
    int n = f.size();
    vector<ll> g(n, 0); // Initialize g with 0s

    // Perform Möbius inversion
    for (int i = 1; i < n; ++i) {
        for (int j = i; j < n; j += i) {
            g[i] += mu[j] * f[j / i]; // Sum contributions weighted by μ(d)
        }
    }
    return g;
}

