// --- NTT Implementation ---

#include <vector>
#include <cmath>
#include <algorithm>

using namespace std;
typedef long long ll;
const int MOD = 998244353; // A large prime number for modulo operations
const int MAXN = 1 << 17; // Maximum size of the polynomial

// --- Fast Power Function ---
ll fpow(ll x, ll y) {
    ll res = 1;
    while (y > 0) {
        if (y & 1) res = res * x % MOD;
        x = x * x % MOD;
        y >>= 1;
    }
    return res;
}

// --- NTT Function ---
void ntt(vector<ll>& a, bool inv) {
    int n = a.size();
    for (int i = 1; i < n; i <<= 1) {
        ll w = fpow(3, (MOD - 1) / (i << 1)); // Primitive root of unity
        if (inv) w = fpow(w, MOD - 2); // Inverse if inverse transform
        for (int j = 0; j < n; j += i << 1) {
            ll wj = 1;
            for (int k = 0; k < i; k++) {
                ll u = a[j + k], v = a[j + k + i] * wj % MOD;
                a[j + k] = (u + v) % MOD;
                a[j + k + i] = (u - v + MOD) % MOD;
                wj = wj * w % MOD;
            }
        }
    }
}

// --- Polynomial Multiplication using NTT ---
vector<ll> multiply(vector<ll>& a, vector<ll>& b) {
    int n = 1;
    while (n < a.size() + b.size()) n <<= 1;
    a.resize(n); b.resize(n);
    ntt(a, false); ntt(b, false);
    for (int i = 0; i < n; i++) a[i] = a[i] * b[i] % MOD;
    ntt(a, true);
    for (int i = 0; i < n; i++) a[i] = a[i] * fpow(n, MOD - 2) % MOD;
    return a;
}

