// --- Pohlig-Hellman Algorithm ---

// Time: O(log p * log n) — Space: O(log p)

#include <vector>
#include <cmath>
#include <numeric>

using namespace std;

// Function to calculate modular exponentiation
long long modExp(long long base, long long exp, long long mod) {
    long long result = 1;
    base = base % mod;
    while (exp > 0) {
        if (exp % 2 == 1)
            result = (result * base) % mod;
        exp = exp >> 1;
        base = (base * base) % mod;
    }
    return result;
}

// Function to calculate modular inverse using Fermat's Little Theorem
long long modInverse(long long a, long long p) {
    return modExp(a, p - 2, p);
}

// Function to solve the discrete logarithm problem using Pohlig-Hellman Algorithm
vector<long long> pohligHellman(long long g, long long h, long long p) {
    int n = log2(p - 1) + 1; // Number of bits in p-1
    vector<long long> x(n); // Result vector

    for (int i = 0; i < n; ++i) {
        long long subp = 1 << i; // 2^i
        long long subg = modExp(g, (p - 1) / subp, p); // g^(p-1)/2^i mod p
        long long subh = modExp(h, (p - 1) / subp, p); // h^(p-1)/2^i mod p
        long long a = 0;
        for (long long j = 0; j < subp; ++j) {
            if ((modExp(subg, j, p) * subh) % p == 1) {
                a = j;
                break;
            }
        }
        x[i] = a;
    }

    // Combine results using Chinese Remainder Theorem
    long long result = 0;
    long long mod = 1;
    for (int i = 0; i < n; ++i) {
        result += x[i] * mod;
        result %= p;
        mod *= (1 << i);
    }

    return {result};
}

