// --- polynomial inverse ---

// Function to compute the inverse of a polynomial modulo X^n using Newton's method and FFT
std::vector<long long> polyInverse(const std::vector<long long>& P, int n) {
    const int MOD = 1e9 + 7;
    std::vector<long long> Q(n);
    Q[0] = modInverse(P[0], MOD); // Initial guess for the inverse

    // Newton's iteration to refine the inverse coefficients
    for (int k = 1; k < n; ++k) {
        Q[k] = 0;
        for (int i = 1; i <= k; ++i) {
            Q[k] = (Q[k] - (long long)P[i] * Q[k-i]) % MOD;
        }
        Q[k] = (Q[k] * 2) % MOD; // Ensure non-negative
    }

    return Q;
}

// --- polynomial multiplication ---

// Function to multiply two polynomials using FFT
std::vector<long long> polyMultiply(const std::vector<long long>& A, const std::vector<long long>& B, int n) {
    std::vector<complex<double>> fa(A.begin(), A.end()), fb(B.begin(), B.end());
    fft(fa, false);
    fft(fb, false);

    for (int i = 0; i < n; ++i) {
        fa[i] *= fb[i];
    }

    fft(fa, true);
    std::vector<long long> res(n);
    for (int i = 0; i < n; ++i) {
        res[i] = round(fa[i].real()) % MOD;
    }

    return res;
}

// --- FFT implementation ---

// Function to perform FFT on a vector of complex numbers
void fft(std::vector<complex<double>>& a, bool inv) {
    int n = a.size();
    for (int i = 1, j = 0; i < n; ++i) {
        int bit = n >> 1;
        while (j >= bit) {
            j -= bit;
            bit >>= 1;
        }
        j += bit;
        if (i < j) {
            std::swap(a[i], a[j]);
        }
    }

    for (int len = 2; len <= n; len <<= 1) {
        double ang = 2 * M_PI / len * (inv ? -1 : 1);
        complex<double> wlen(cos(ang), sin(ang));
        for (int i = 0; i < n; i += len) {
            complex<double> w(1);
            for (int j = 0; j < len / 2; ++j) {
                complex<double> u = a[i + j], v = a[i + j + len / 2] * w;
                a[i + j] = u + v;
                a[i + j + len / 2] = u - v;
                w *= wlen;
            }
        }
    }

    if (inv) {
        for (int i = 0; i < n; ++i) {
            a[i] /= n;
        }
    }
}

// --- utility functions ---

// Function to compute modular inverse using Fermat's little theorem
long long modInverse(long long a, int MOD) {
    return power(a, MOD - 2, MOD);
}

// Function to compute (a^b) % MOD using binary exponentiation
long long power(long long a, int b, int MOD) {
    long long res = 1;
    a %= MOD;
    while (b > 0) {
        if (b & 1) {
            res = (res * a) % MOD;
        }
        a = (a * a) % MOD;
        b >>= 1;
    }
    return res;
}

// --- usage example ---

// Example usage in a contest problem
int main() {
    std::vector<long long> P = {3, 1}; // Polynomial P(X) = 3 + X
    int n = 2; // Modulo X^2
    std::vector<long long> Q = polyInverse(P, n); // Compute inverse Q(X)

    // Output the result
    for (int i = 0; i < n; ++i) {
        std::cout << Q[i] << " ";
    }
    return 0;
}

