// --- Time: O(n^(2/3)) -- Space: O(n)

#include <vector>
#include <cmath>

// Function to compute the sum of Euler's totient function from 1 to n using min-25 sieve approach
long long totientSum(int n) {
    std::vector<int> spf(n + 1); // smallest prime factor array
    std::vector<long long> phi(n + 1, 0); // totient function array

    // --- build SPF array ---
    for (int i = 2; i <= n; ++i) {
        if (spf[i] == 0) { // i is prime
            spf[i] = i;
            phi[i] = i - 1;
        }
        for (int j = i; j <= n; j += i) {
            if (spf[j] == 0) spf[j] = i; // set smallest prime factor
            phi[j] -= phi[j] / i; // update totient function
        }
    }

    // --- compute sum of totient values ---
    long long sum = 0;
    for (int i = 1; i <= n; ++i) {
        sum += phi[i];
    }
    return sum;
}

