// --- CDQ Divide & Conquer Implementation ---

#include <vector>
#include <algorithm>

// --- CDQ Data Structure ---
struct CDQ {
    std::vector<int> a, b;
    int n;

    CDQ(std::vector<int>& arr) : a(arr), b(arr), n(arr.size()) {}

    // --- CDQ Divide & Conquer Function ---
    void cdq(int l, int r) {
        if (l == r) return;
        int mid = (l + r) / 2;

        // --- Sort by b values ---
        std::sort(a.begin() + l, a.begin() + r + 1, [&](int i, int j) {
            return b[i] < b[j];
        });

        // --- Process left half ---
        cdq(l, mid);

        // --- Merge and process right half ---
        for (int i = l; i <= r; ++i) {
            if (a[i] > mid) {
                b[a[i]] += mid - a[i] + 1;
            }
        }
        cdq(mid + 1, r);
    }

    // --- Query Function ---
    int query(int x) {
        return b[x];
    }
};

