// --- Simulated Annealing Implementation ---

#include <vector>
#include <algorithm>
#include <random>
#include <cmath>

// --- Complexity ---
// Time: O(n^2 * log(T)) - n is the number of elements, T is the temperature
// Space: O(1) - constant space for variables

// --- Simulated Annealing Function ---
long long simulatedAnnealing(std::vector<int>& arr) {
    std::random_device rd;
    std::mt19937 g(rd());
    int n = arr.size();
    long long bestCost = 0, currentCost = 0;

    // --- Calculate initial cost ---
    for (int i = 0; i < n - 1; ++i) {
        currentCost += std::abs(arr[i] - arr[i + 1]);
    }
    bestCost = currentCost;

    // --- Simulated Annealing Loop ---
    double T = 1000.0, alpha = 0.95;
    while (T > 1e-6) {
        for (int i = 0; i < n - 1; ++i) {
            std::uniform_int_distribution<> dis(0, n - 2);
            int j = dis(g);
            std::swap(arr[j], arr[j + 1]);

            long long newCost = 0;
            for (int k = 0; k < n - 1; ++k) {
                newCost += std::abs(arr[k] - arr[k + 1]);
            }

            if (newCost < currentCost || std::exp(-(newCost - currentCost) / T) > std::uniform_real_distribution<>(0.0, 1.0)(g)) {
                currentCost = newCost;
                if (currentCost < bestCost) {
                    bestCost = currentCost;
                }
            } else {
                std::swap(arr[j], arr[j + 1]); // Revert swap
            }
        }
        T *= alpha;
    }

    return bestCost;
}

// --- Usage Example ---
// int main() {
//     std::vector<int> arr = {3, 1, 4, 1, 5};
//     long long result = simulatedAnnealing(arr);
//     std::cout << "Minimum adjacent pair sum: " << result << std::endl;
//     return 0;
// }

// --- Notes ---
// - This implementation uses a simple cooling schedule and random swaps.
// - The acceptance probability formula is based on the Metropolis criterion.
// - The initial temperature and cooling rate are set to typical values.
// - The algorithm assumes the input array is not empty.

