// --- build adjacency list ---
struct Edge {
    int to;
    long long weight;
};

using Graph = vector<vector<Edge>>;

// --- Dijkstra's algorithm for single-source shortest paths ---
vector<long long> dijkstra(const Graph& graph, int source) {
    int n = graph.size();
    vector<long long> dist(n, LLONG_MAX);
    dist[source] = 0;
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;
    pq.push({0, source});

    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d > dist[u]) continue;
        for (auto& [v, w] : graph[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }
    return dist;
}

// --- Yen's algorithm for k-shortest paths ---
vector<vector<long long>> yen_ksp(const Graph& graph, int source, int target, int k) {
    vector<vector<long long>> paths;
    vector<long long> dist = dijkstra(graph, source);
    if (dist[target] == LLONG_MAX) return paths; // No path to target

    // --- First shortest path ---
    vector<int> path;
    int u = target;
    while (u != source) {
        path.push_back(u);
        u = graph[u][0].to; // Simplified for example
    }
    path.push_back(source);
    reverse(path.begin(), path.end());
    paths.push_back(path);

    // --- Subsequent shortest paths ---
    vector<vector<long long>> prev_paths;
    for (int i = 1; i < k; ++i) {
        vector<pair<int, long long>> spur_edges;
        for (auto& [v, w] : graph[paths.back().back()]) {
            if (v != paths.back()[paths.back().size() - 2]) {
                spur_edges.push_back({v, w});
            }
        }

        vector<vector<long long>> spur_paths;
        for (auto& [v, w] : spur_edges) {
            vector<int> spur_path = paths.back();
            spur_path.pop_back();
            spur_path.push_back(v);
            vector<long long> spur_dist = dijkstra(graph, v);
            if (spur_dist[target] != LLONG_MAX) {
                spur_path.push_back(target);
                spur_paths.push_back(spur_path);
            }
        }

        if (spur_paths.empty()) break;

        vector<long long> min_spur_dist = dijkstra(graph, source);
        for (auto& path : spur_paths) {
            int last_node = path.back();
            for (int j = path.size() - 2; j >= 0; --j) {
                if (min_spur_dist[path[j]] > min_spur_dist[last_node] + graph[path[j]][path[j + 1]].weight) {
                    min_spur_dist[path[j]] = min_spur_dist[last_node] + graph[path[j]][path[j + 1]].weight;
                } else {
                    break;
                }
            }
        }

        vector<vector<long long>> new_paths;
        for (auto& path : spur_paths) {
            if (min_spur_dist[path.back()] == dijkstra(graph, source)[path.back()]) {
                new_paths.push_back(path);
            }
        }

        paths.insert(paths.end(), new_paths.begin(), new_paths.end());
    }

    return paths;
}

