// --- build adjacency list ---
std::vector<std::vector<int>> build_adjacency_list(const std::vector<std::vector<int>>& tables) {
    int n = tables.size();
    std::vector<std::vector<int>> adj(n);
    for (int i = 0; i < n - 1; ++i) {
        for (int x : tables[i]) {
            auto it = std::lower_bound(tables[i + 1].begin(), tables[i + 1].end(), x);
            if (it != tables[i + 1].end() && *it == x) {
                adj[i].push_back(it - tables[i + 1].begin());
            } else {
                adj[i].push_back(-1); // Not found
            }
        }
    }
    return adj;
}

// --- perform fractional cascading search ---
int fractional_cascading_search(const std::vector<std::vector<int>>& tables, const std::vector<std::vector<int>>& adj, int target) {
    int n = tables.size();
    int pos = std::lower_bound(tables[0].begin(), tables[0].end(), target) - tables[0].begin();
    for (int i = 1; i < n; ++i) {
        if (pos == -1) break;
        pos = adj[i - 1][pos];
    }
    return pos;
}

// --- main function for demonstration ---
int main() {
    std::vector<std::vector<int>> tables = {{3, 5, 7}, {2, 4, 6, 8}, {1, 3, 5}};
    auto adj = build_adjacency_list(tables);
    int target = 6;
    int result = fractional_cascading_search(tables, adj, target);
    std::cout << "Result: " << result << std::endl; // Output should be the position of 6 in the last table
    return 0;
}

