// --- build suffix array ---
std::vector<int> buildSuffixArray(const std::string& s) {
    int n = s.size();
    std::vector<int> sa(n), rank(n);
    for (int i = 0; i < n; ++i) sa[i] = i, rank[i] = s[i];
    for (int k = 1; k < n; k <<= 1) {
        std::vector<int> newRank(n), cnt(n + 1);
        for (int i = 0; i < n; ++i) cnt[rank[i]]++;
        for (int i = 1; i <= n; ++i) cnt[i] += cnt[i - 1];
        for (int i = n - 1; i >= 0; --i) {
            int prev = sa[i] - k;
            if (prev < 0) prev += n;
            newRank[sa[i]] = cnt[rank[prev]]++;
        }
        rank.swap(newRank);
    }
    return sa;
}

// --- build LCP array ---
std::vector<int> buildLCP(const std::string& s, const std::vector<int>& sa) {
    int n = s.size();
    std::vector<int> lcp(n), rank(n);
    for (int i = 0; i < n; ++i) rank[sa[i]] = i;
    for (int i = 0, h = 0; i < n; ++i) {
        if (rank[i] == n - 1) h = 0;
        else {
            int j = sa[rank[i] + 1];
            while (i + h < n && j + h < n && s[i + h] == s[j + h]) ++h;
            lcp[rank[i]] = h;
        }
    }
    return lcp;
}

// --- RMQ on LCP array ---
struct SparseTable {
    std::vector<std::vector<int>> table;
    SparseTable(const std::vector<int>& arr) {
        int n = arr.size(), k = 32 - __builtin_clz(n);
        table.assign(k, arr);
        for (int j = 1; j < k; ++j)
            for (int i = 0; i + (1 << j) <= n; ++i)
                table[j][i] = std::min(table[j - 1][i], table[j - 1][i + (1 << (j - 1))]);
    }
    int query(int l, int r) {
        int k = 32 - __builtin_clz(r - l + 1);
        return std::min(table[k][l], table[k][r - (1 << k) + 1]);
    }
};

// --- LCP applications ---
int maxRepeatingSubstring(const std::string& s) {
    std::vector<int> sa = buildSuffixArray(s);
    std::vector<int> lcp = buildLCP(s, sa);
    SparseTable st(lcp);
    int maxLen = 0;
    for (int i = 0; i < sa.size(); ++i) {
        int len = st.query(i + 1, sa.size() - 1);
        maxLen = std::max(maxLen, len);
    }
    return maxLen;
}

