// --- build suffix array ---
std::vector<int> buildSuffixArray(const std::string& s) {
    int n = s.size();
    std::vector<int> sa(n), rank(n);
    for (int i = 0; i < n; ++i) sa[i] = i, rank[i] = s[i];
    for (int k = 1; k < n; k <<= 1) {
        std::vector<int> newRank(n), count(n + 1);
        for (int i = 0; i < n; ++i) count[rank[i]]++;
        for (int i = 1; i <= n; ++i) count[i] += count[i - 1];
        for (int i = n - 1; i >= 0; --i) {
            int prev = (sa[i] - k + n) % n;
            newRank[prev] = count[rank[prev]] - 1;
        }
        rank = newRank;
    }
    return sa;
}

// --- build LCP array using Kasai's Algorithm ---
std::vector<int> kasai(const std::string& s, const std::vector<int>& sa) {
    int n = s.size();
    std::vector<int> rank(n), lcp(n);
    for (int i = 0; i < n; ++i) rank[sa[i]] = i;
    int k = 0;
    for (int i = 0; i < n; ++i) {
        if (rank[i] == n - 1) {
            k = 0;
            continue;
        }
        int j = sa[rank[i] + 1];
        while (i + k < n && j + k < n && s[i + k] == s[j + k]) ++k;
        lcp[rank[i]] = k;
        if (k > 0) --k;
    }
    return lcp;
}

