// --- build adjacency list ---
std::vector<std::unordered_map<char, int>> adj;
std::vector<int> link, len;

// --- add character to SAM ---
void add_char(int c) {
    int u = adj.size() - 1;
    int v = adj.size();
    adj.push_back({c, v});
    len.push_back(len[u] + 1);
    link.push_back(0);

    int p = u;
    while (p != -1 && !adj[p].count(c)) {
        adj[p][c] = v;
        p = link[p];
    }

    if (p == -1) {
        link[v] = 0;
    } else {
        int q = adj[p][c];
        if (len[q] == len[p] + 1) {
            link[v] = q;
        } else {
            int clone = adj.size();
            adj.push_back(adj[q]);
            len.push_back(len[p] + 1);
            link.push_back(link[q]);

            while (p != -1 && adj[p][c] == q) {
                adj[p][c] = clone;
                p = link[p];
            }

            link[q] = clone;
            link[v] = clone;
        }
    }
}

// --- build SAM for a string ---
void build_sam(const std::string& s) {
    adj.clear();
    link.clear();
    len.clear();

    adj.push_back({});
    link.push_back(-1);
    len.push_back(0);

    for (char c : s) {
        add_char(c);
    }
}

// --- find LCS length between two strings using SAMs ---
int lcs(const std::string& a, const std::string& b) {
    build_sam(a);
    int max_len = 0;

    for (char c : b) {
        int u = adj.size() - 1;
        while (u != -1 && !adj[u].count(c)) {
            u = link[u];
        }

        if (u != -1) {
            max_len = std::max(max_len, len[u]);
        }
    }

    return max_len;
}

